window.CODE_INDEX = {"classes":{"Coordinator":{"code":"/// Coordinator: Protocol for handling navigation. A coordinator owns a navigation flow, and handles the presentation of view controllers.\n/// It can handle the dependencies of the View Controllers it manages.\n/// Properties:\n/// - navigationController: The navigation controller that the coordinator uses to manage view controllers.\n/// Methods:\n/// start():  Starts the coordinator's navigation flow. Should be called to trigger the presentation of the View Controllers. Returns boolean of whether navigation succeeded or not.\n@MainActor\nprotocol Coordinator: AnyObject {\n    var navigationController: UINavigationController { get }\n\n    @discardableResult\n    func start() -> Bool\n}","file":"Wikipedia/Code/Coordinator.swift","kind":"protocol","line":3,"members":{"navigationController":[11,11],"start":[13,14]},"supers":["AnyObject"]},"LogoutCoordinatorDelegate":{"code":"@MainActor\nprotocol LogoutCoordinatorDelegate: AnyObject {\n    func didTapLogout(authInstrument: InstrumentImpl)\n}","file":"Wikipedia/Code/LogoutCoordinatorDelegate.swift","kind":"protocol","line":4,"members":{"didTapLogout":[6,6]},"supers":["AnyObject"]},"MEPEventsProviding":{"code":"public protocol MEPEventsProviding {\n    var eventLoggingCategory: EventCategoryMEP { get }\n    var eventLoggingLabel: EventLabelMEP? { get }\n}","file":"WMF Framework/Event Platform/MEPEventProviding.swift","kind":"protocol","line":54,"members":{"eventLoggingCategory":[55,55],"eventLoggingLabel":[56,56]},"supers":[]},"NSObject":{"alsoIn":["WikipediaUnitTests/Code/NSObject+WMFReflection.m"],"code":"/**\n *  Reflection utilities inspired by Mantle's runtime methods.\n */\n@interface NSObject (WMFReflection)\n\n+ (void)wmf_enumeratePropertiesUntilSuperclass:(Class)superClass usingBlock:(WMFObjCPropertyEnumerator)block;\n\n@end","file":"WikipediaUnitTests/Code/NSObject+WMFReflection.h","kind":"category","line":5,"members":{"wmf_enumeratePropertiesUntilSuperclass:usingBlock:":[10,10]},"supers":[]},"SearchLanguagesBarViewController":{"alsoIn":["Wikipedia/Code/SearchLanguagesBarViewController.swift"],"appearsIn":[["search","h-classes","Logic \u00b7 class diagram"],["search","h-widgets","Screen \u00b7 view composition"]],"code":"class SearchLanguagesBarViewController: ThemeableViewController, WMFPreferredLanguagesViewControllerDelegate, WMFLanguagesViewControllerDelegate {\n    required init() {\n        super.init(nibName: \"SearchLanguagesBarViewController\", bundle: nil)\n    }\n    \n    required init?(coder aDecoder: NSCoder) {\n        fatalError(\"init(coder:) has not been implemented\")\n    }\n    \n    @objc weak var delegate: SearchLanguagesBarViewControllerDelegate?\n\n    @IBOutlet fileprivate var otherLanguagesButton: UIButton?\n    @IBOutlet weak var otherLanguagesButtonBackgroundView: UIView!\n    @IBOutlet weak var scrollView: UIScrollView!\n    @IBOutlet weak var gradientView: WMFGradientView!\n    \n    fileprivate var moreLanguagesTip = MoreLanguagesTip()\n    fileprivate var moreLanguagesTipObservationTask: Task<Void, Never>?\n    fileprivate weak var tooltipVC: TipUIPopoverViewController?\n\n    lazy var stackView: UIStackView = {\n        let stackView = UIStackView()\n        stackView.translatesAutoresizingMaskIntoConstraints = false\n        stackView.axis = .horizontal\n        stackView.distribution = .fill\n        stackView.alignment = .fill\n        stackView.spacing = 8\n        return stackView\n    }()\n\n    fileprivate var selectedSearchContentLanguageCode: String? {\n        get {\n            if let contentLanguageCode = UserDefaults.standard.wmf_currentSearchContentLanguageCode() {\n                return contentLanguageCode\n            } else {\n                \n                if let appContentLanguageCode = MWKDataStore.shared().languageLinkController.appLanguage?.contentLanguageCode {\n                    self.selectedSearchContentLanguageCode = appContentLanguageCode\n                    return appContentLanguageCode\n                } else {\n                    assertionFailure(\"appLanguage should have been set at this point\")\n                    return nil\n                }\n            }\n        }\n        set {\n            UserDefaults.standard.wmf_setCurrentSearchContentLanguageCode(newValue)\n            if let newValue {\n                delegate?.searchLanguagesBarViewController(self, didChangeSelectedSearchContentLanguageCode: newValue)\n            }\n            updateSearchLanguageButtons()\n        }\n    }\n    \n    var selectedSiteURL: URL? {\n        let selectedLanguageLink = languageBarLanguages().first { $0.contentLanguageCode == selectedSearchContentLanguageCode }\n        return selectedLanguageLink?.siteURL\n    }\n    \n    func moveScrollViewToStart() {\n        scrollView.setContentOffset(.zero, animated: false)\n    }\n\n    override func viewDidLoad() {\n        super.viewDidLoad()\n\n        if #available(iOS 26, *) {\n            let effectView = UIVisualEffectView(effect: UIBlurEffect(style: .systemMaterial))\n            effectView.translatesAutoresizingMaskIntoConstraints = false\n            view.insertSubview(effectView, at: 0)\n            NSLayoutConstraint.activate([\n                effectView.leadingAnchor.constraint(equalTo: view.leadingAnchor),\n                effectView.trailingAnchor.constraint(equalTo: view.trailingAnchor),\n                effectView.topAnchor.constraint(equalTo: view.topAnchor),\n                effectView.bottomAnchor.constraint(equalTo: view.bottomAnchor)\n            ])\n        }\n\n        otherLanguagesButton?.setTitle(WMFLocalizedString(\"main-menu-title\", value:\"More\", comment:\"Title for menu of secondary items. {{Identical|More}}\"), for: .normal)\n        otherLanguagesButton?.titleLabel?.font = WMFFont.for(.body)\n\n        if let otherLanguagesButton {\n            var deprecatedOtherLanguagesButton = otherLanguagesButton as DeprecatedButton\n            deprecatedOtherLanguagesButton.deprecatedTitleEdgeInsets = UIEdgeInsets(top: 0, left: 0, bottom: 5, right: 0)\n        }\n        \n        \n        NotificationCenter.default.addObserver(self, selector: #selector(appLanguageDidChange(_:)), name: NSNotification.Name.WMFAppLanguageDidChange, object: nil)\n        NotificationCenter.default.addObserver(self, selector: #selector(preferredLanguagesDidChange(_:)), name: NSNotification.Name.WMFPreferredLanguagesDidChange, object: nil)\n\n        addSearchLanguageButtonStackView()\n\n        apply(theme: theme)\n        view.wmf_configureSubviewsForDynamicType()\n\n        let isRTL = view.effectiveUserInterfaceLayoutDirection == .rightToLeft\n\n        gradientView.translatesAutoresizingMaskIntoConstraints = false\n        gradientView.startPoint = isRTL ? CGPoint(x: 0.7, y: 0) : .zero\n        gradientView.endPoint = isRTL ? .zero : CGPoint(x: 0.7, y: 0)\n        gradientView.isUserInteractionEnabled = false\n\n        scrollView.clipsToBounds = true\n    }\n\n    fileprivate func addSearchLanguageButtonStackView() {\n        scrollView.addSubview(stackView)\n\n        stackView.leadingAnchor.constraint(equalTo: scrollView.leadingAnchor).isActive = true\n        stackView.trailingAnchor.constraint(equalTo: scrollView.trailingAnchor).isActive = true\n        stackView.topAnchor.constraint(equalTo: scrollView.topAnchor).isActive = true\n        stackView.bottomAnchor.constraint(equalTo: scrollView.bottomAnchor).isActive = true\n        stackView.heightAnchor.constraint(equalTo: scrollView.heightAnchor).isActive = true\n    }\n    \n    override func viewDidLayoutSubviews() {\n        super.viewDidLayoutSubviews()\n\n        let isRTL = view.effectiveUserInterfaceLayoutDirection == .rightToLeft\n        let defaultContentInset: CGFloat = 8\n        let gradientFrameInset = gradientView.frame.size.width / 1.5\n        let preferredLeftInset = isRTL ? gradientFrameInset : defaultContentInset\n        let preferredRightInset = isRTL ? defaultContentInset : gradientFrameInset\n\n        scrollView.contentInset = UIEdgeInsets(top: 0, left: preferredLeftInset, bottom: 0, right: preferredRightInset)\n        scrollView.scrollIndicatorInsets = UIEdgeInsets(top: 0, left: preferredLeftInset, bottom: -5, right: preferredRightInset)\n    }\n    \n    deinit {\n        NotificationCenter.default.removeObserver(self)\n    }\n    \n    override func viewWillAppear(_ animated: Bool) {\n        super.viewWillAppear(animated)\n        updateSearchLanguageButtons()\n    }\n    \n    override func viewDidAppear(_ animated: Bool) {\n        super.viewDidAppear(animated)\n        self.listenForMoreLanguagesTooltip()\n    }\n    \n    override func viewWillDisappear(_ animated: Bool) {\n        super.viewWillDisappear(animated)\n        moreLanguagesTipObservationTask?.cancel()\n        moreLanguagesTipObservationTask = nil\n    }\n    \n    fileprivate func languageBarLanguages() -> [MWKLanguageLink] {\n        return MWKDataStore.shared().languageLinkController.preferredLanguages\n    }\n\n    fileprivate func searchLanguageButtons() -> [SearchLanguageButton] {\n        return stackView.arrangedSubviews.compactMap { $0 as? SearchLanguageButton }\n    }\n    \n    fileprivate func updateSearchLanguageButtons() {\n        guard let currentlySelectedContentLanguageCode = selectedSearchContentLanguageCode else {\n            assertionFailure(\"No current app content language code\")\n            return\n        }\n\n        stackView.subviews.forEach { $0.removeFromSuperview() }\n        let languageBarLanguages = self.languageBarLanguages()\n\n        for language in languageBarLanguages {\n            let button = SearchLanguageButton()\n\n            button.languageCode = language.languageCode\n            button.contentLanguageCode = language.contentLanguageCode\n            button.isSelected = language.contentLanguageCode == currentlySelectedContentLanguageCode\n            button.addTarget(self, action: #selector(setCurrentlySelectedLanguageToButtonLanguage(withSender:)), for: .primaryActionTriggered)\n            button.setTitle((language.name as NSString).wmf_stringByCapitalizingFirstCharacter(usingWikipediaLanguageCode: nil), for: .normal)\n\n            stackView.addArrangedSubview(button)\n        }\n\n        scrollToSelectedSearchLanguageButton()\n        apply(theme: theme)\n        \n        MoreLanguagesTip.numberOfAppLanguages = languageBarLanguages.count\n    }\n\n    fileprivate func scrollToSelectedSearchLanguageButton() {\n        guard let selectedButton = searchLanguageButtons().first(where: { $0.isSelected }) else {\n            return\n        }\n\n        view.layoutIfNeeded()\n        scrollView.scrollRectToVisible(selectedButton.frame, animated: true)\n    }\n    \n    @objc fileprivate func setCurrentlySelectedLanguageToButtonLanguage(withSender sender: SearchLanguageButton) {\n        guard let senderLanguage = languageBarLanguages().first(where: { $0.contentLanguageCode == sender.contentLanguageCode }) else {\n            assertionFailure(\"Language for button not found\")\n            return\n        }\n\n        selectedSearchContentLanguageCode = senderLanguage.contentLanguageCode\n    }\n    \n    @IBAction fileprivate func openLanguagePicker() {\n        let languagesVC = WMFPreferredLanguagesViewController.preferredLanguagesViewController()\n        languagesVC.delegate = self\n        if let themeable = languagesVC as Themeable? {\n            themeable.apply(theme: self.theme)\n        }\n        let navVC = WMFComponentNavigationController(rootViewController: languagesVC, modalPresentationStyle: .overFullScreen)\n        present(navVC, animated: true, completion: nil)\n    }\n    \n    func languagesController(_ controller: WMFLanguagesViewController, didSelectLanguage language: MWKLanguageLink) {\n        // If the selected language will not be displayed because we only display max 3 languages, move it to index 2\n        if languageBarLanguages().firstIndex(of: language) == nil && languageBarLanguages().count > 2 {\n            MWKDataStore.shared().languageLinkController.reorderPreferredLanguage(language, to: 2)\n        }\n        \n        selectedSearchContentLanguageCode = language.contentLanguageCode\n        controller.dismiss(animated: true, completion: nil)\n    }\n    \n    @objc func appLanguageDidChange(_ notification: Notification) {\n        guard let langController = notification.object, let appLanguage = (langController as AnyObject).appLanguage else {\n            assertionFailure(\"Could not extract app language from WMFAppLanguageDidChangeNotification\")\n            return\n        }\n        selectedSearchContentLanguageCode = appLanguage?.contentLanguageCode\n    }\n    \n    @objc func preferredLanguagesDidChange(_ notification: Notification) {\n        updateSearchLanguageButtons()\n    }\n    \n    override func apply(theme: Theme) {\n        super.apply(theme: theme)\n        guard viewIfLoaded != nil else {\n            return\n        }\n        if #available(iOS 26, *) {\n            view.backgroundColor = .clear\n            otherLanguagesButtonBackgroundView?.backgroundColor = .clear\n            let blurColor = theme.colors.paperBackground.withAlphaComponent(0)\n            gradientView.setStart(blurColor, end: blurColor)\n        } else {\n            let bgColor = theme.colors.paperBackground\n            view.backgroundColor = bgColor\n            otherLanguagesButtonBackgroundView?.backgroundColor = bgColor\n            gradientView.setStart(bgColor.withAlphaComponent(0), end: bgColor)\n        }\n        for languageButton in searchLanguageButtons() {\n            languageButton.apply(theme: theme)\n        }\n        otherLanguagesButton?.setTitleColor(theme.colors.link, for: .normal)\n    }\n    \n    func listenForMoreLanguagesTooltip() {\n        moreLanguagesTipObservationTask =  Task { @MainActor in\n            for await status in  moreLanguagesTip.statusUpdates {\n                switch status {\n                case .available:\n                    if let button = otherLanguagesButton {\n                        let popoverController = TipUIPopoverViewController(moreLanguagesTip, sourceItem: button)\n                        self.tooltipVC = popoverController\n                        present(popoverController, animated: true) {\n                            popoverController.presentationController?.delegate = self\n                        }\n                    }\n                case .invalidated:\n                    if let tooltipVC = self.tooltipVC {\n                        tooltipVC.presentationController?.delegate = nil\n                        tooltipVC.dismiss(animated: true)\n                        self.tooltipVC = nil\n                    }\n                    break\n                default:\n                    continue\n                }\n            }\n        }\n    }\n}","file":"Wikipedia/Code/SearchLanguagesBarViewController.swift","kind":"class","line":113,"members":{"SearchLanguagesBarViewController":[114,116],"addSearchLanguageButtonStackView":[218,226],"appLanguageDidChange":[334,340],"apply":[346,366],"deinit":[241,243],"delegate":[122,122],"gradientView":[127,127],"languageBarLanguages":[261,263],"languagesController":[324,332],"listenForMoreLanguagesTooltip":[368,392],"moreLanguagesTip":[129,129],"moreLanguagesTipObservationTask":[130,130],"moveScrollViewToStart":[172,174],"openLanguagePicker":[314,322],"otherLanguagesButton":[124,124],"otherLanguagesButtonBackgroundView":[125,125],"preferredLanguagesDidChange":[342,344],"presentationControllerDidDismiss":[422,426],"scrollToSelectedSearchLanguageButton":[296,303],"scrollView":[126,126],"searchLanguageButtons":[265,267],"selectedSearchContentLanguageCode":[143,165],"selectedSiteURL":[167,170],"setCurrentlySelectedLanguageToButtonLanguage":[305,312],"stackView":[133,141],"tooltipVC":[131,131],"updateSearchLanguageButtons":[269,294],"viewDidAppear":[250,253],"viewDidLayoutSubviews":[228,239],"viewDidLoad":[176,216],"viewWillAppear":[245,248],"viewWillDisappear":[255,259]},"supers":["ThemeableViewController","WMFPreferredLanguagesViewControllerDelegate","WMFLanguagesViewControllerDelegate","UIAdaptivePresentationControllerDelegate"]},"SearchLanguagesBarViewControllerDelegate":{"code":"@objc protocol SearchLanguagesBarViewControllerDelegate: AnyObject {\n    func searchLanguagesBarViewController(_ controller: SearchLanguagesBarViewController, didChangeSelectedSearchContentLanguageCode contentLanguageCode: String)\n}","file":"Wikipedia/Code/SearchLanguagesBarViewController.swift","kind":"protocol","line":7,"members":{"searchLanguagesBarViewController":[8,8]},"supers":["AnyObject"]},"SearchResultsLoader":{"appearsIn":[["search","h-classes","Logic \u00b7 class diagram"],["search","h-sequence","Type a query \u00b7 sequence"]],"code":"struct SearchResultsLoader {\n\n    enum Failure: Error {\n        case fetch(Error, WMFSearchType)\n    }\n\n    /// The results of a search. The full text rows come after the prefix rows, so the count of\n    /// prefix rows says which request gave each row.\n    struct Outcome {\n        let results: WMFSearchResults\n        let type: WMFSearchType\n        let prefixResultCount: Int\n\n        /// Which request gave the row at `index`.\n        func type(ofRow index: Int) -> WMFSearchType {\n            index < prefixResultCount ? .prefix : .full\n        }\n    }\n\n    static let fullTextSearchThreshold = 12\n\n    let fetcher: WMFSearchFetcher\n\n    func fetchResults(for searchTerm: String, siteURL: URL, resultLimit: UInt = WMFMaxSearchResultLimit) async throws -> Outcome {\n        let prefixResults: WMFSearchResults\n        do {\n            prefixResults = try await fetcher.fetchArticles(forSearchTerm: searchTerm, siteURL: siteURL, resultLimit: resultLimit)\n        } catch let error as CancellationError {\n            throw error\n        } catch {\n            throw Failure.fetch(error, .prefix)\n        }\n\n        let prefixCount = prefixResults.results?.count ?? 0\n        guard prefixCount < Self.fullTextSearchThreshold else {\n            return Outcome(results: prefixResults, type: .prefix, prefixResultCount: prefixCount)\n        }\n\n        try Task.checkCancellation()\n\n        do {\n            let fullTextResults = try await fetcher.fetchArticles(forSearchTerm: searchTerm, siteURL: siteURL, resultLimit: resultLimit, fullTextSearch: true, appendToPreviousResults: prefixResults)\n            return Outcome(results: fullTextResults, type: .full, prefixResultCount: prefixCount)\n        } catch let error as CancellationError {\n            throw error\n        } catch {\n            guard prefixCount > 0 else {\n                throw Failure.fetch(error, .full)\n            }\n            return Outcome(results: prefixResults, type: .prefix, prefixResultCount: prefixCount)\n        }\n    }\n}","file":"Wikipedia/Code/SearchResultsLoader.swift","kind":"struct","line":9,"members":{"fetchResults":[32,60],"fetcher":[30,30],"fullTextSearchThreshold":[28,28]},"supers":[]},"SearchResultsViewController":{"alsoIn":["Wikipedia/Code/SearchInstrumentation.swift","Wikipedia/Code/SearchResultsViewController.swift","Wikipedia/Code/SearchResultsViewController.swift","Wikipedia/Code/SearchResultsViewController.swift","Wikipedia/Code/SearchResultsViewController+ResultsList.swift","Wikipedia/Code/SearchResultsViewController+ResultsList.swift"],"appearsIn":[["search","h-classes","Logic \u00b7 class diagram"],["search","h-widgets","Screen \u00b7 view composition"],["search","h-sequence","Type a query \u00b7 sequence"]],"code":"/// This class is designed to be used exclusively as a `UISearchController.searchResultsController`.\nclass SearchResultsViewController: ThemeableViewController, WMFNavigationBarConfiguring, MEPEventsProviding, ShareableArticlesProvider {\n\n    // MARK: - Event Logging Source\n\n    @objc enum EventLoggingSource: Int {\n        case searchTab\n        case topOfFeed\n        case article\n        case unknown\n        /// Picking a link target in the editor. It stays out of the search instrumentation and\n        /// the semantic search experiment.\n        case editor\n    }\n\n    var eventLoggingCategory: EventCategoryMEP { .history }\n    var eventLoggingLabel: EventLabelMEP? { nil }\n\n    // MARK: - Public configuration\n\n    typealias NeedsNewTab = Bool\n    \n    /// Called whenever a search result row or long-press result is tapped. Caller is responsible\n    /// for navigating to the given URL.\n    var articleTappedAction: ((URL, NeedsNewTab) -> Void)?\n\n    /// Called with the query and the project of the search when the reader taps the semantic\n    /// search entry point.\n    /// Follows the search into the sheet of passages and the article. The search screen owns it.\n    let instrumentation: SearchInstrumentation\n\n    var semanticSearchTappedAction: (@MainActor @Sendable (String, WMFProject) -> Void)?\n\n    /// Called when the reader taps the button of the toast shown after hiding the semantic\n    /// search entry point. Caller is responsible for opening the Search settings.\n    var semanticSearchSettingsTappedAction: (@MainActor @Sendable () -> Void)?\n\n    /// Called with the search language code when the reader taps the info button of the\n    /// semantic search entry point.\n    var semanticSearchInfoTappedAction: (@MainActor @Sendable (String) -> Void)?\n\n    /// Called when the user selects a recently-searched term so the parent can write the text into\n    /// its own search bar and activate it.\n    var populateSearchBarAction: ((String) -> Void)?\n\n    /// Controls whether the language picker bar is shown at the top of this VC.\n    var showLanguageBar: Bool = true {\n        didSet {\n            guard isViewLoaded else { return }\n            updateLanguageBarVisibility()\n        }\n    }\n\n    // MARK: - Private properties\n\n    let source: EventLoggingSource\n    let dataStore: MWKDataStore\n\n    /// Parent view controllers that need their own `UISearchControllerDelegate` callbacks should set\n    /// this property. `SearchResultsViewController` will handle all iPad 26 search-UI workarounds\n    /// and then forward every delegate call to the parent.\n    weak var parentSearchControllerDelegate: UISearchControllerDelegate?\n\n    private lazy var searchBarIPadCustomizer: SearchBarIPadCustomizer = {\n        let customizer = SearchBarIPadCustomizer(theme: theme)\n        customizer.onClearTapped = { [weak self] _ in\n            self?.instrumentation.logSearchClose()\n            self?.resetSearchResults()\n        }\n        customizer.onBackTapWillDismiss = { [weak self] in self?.instrumentation.logSearchBack() }\n        customizer.onWillDismiss = { [weak self] in\n            guard let self else { return }\n            resetSearchResults()\n        }\n        return customizer\n    }()\n\n    private let contentContainerView = UIView()\n    private weak var currentEmbeddedViewController: UIViewController?\n\n    var isShowingSearchResults: Bool {\n        currentEmbeddedViewController === resultsViewController\n    }\n\n    private var searchLanguageBarViewController: SearchLanguagesBarViewController?\n    private var needsAnimateLanguageBarMovement = false\n\n    private var searchTerm: String?\n    private var lastSearchSiteURL: URL?\n    private var _siteURL: URL?\n    private var searchTask: Task<Void, Never>?\n\n    var focusesFirstResultWhenKeyboardHides = false\n    var displayedSearchTerm: String?\n    var displayedSiteURL: URL?\n    /// The lexical results on screen and how they came, for the events of the taps on them.\n    private(set) var displayedSearchResults: SearchResultsLoader.Outcome?\n    /// The recent search the reader tapped. The search it starts says so in its init event.\n    private var recentSearchTermPendingInit: String?\n    /// The reader used the keyboard microphone for the text in the search bar.\n    private var isDictating = false\n    /// The text an edit by the reader would leave in the search bar. The clear button empties the\n    /// bar without asking for that edit, so an empty bar that doesn't match it is a tap on clear.\n    var expectedSearchBarText: String?\n    var searchResultsByArticleURL: [String: MWKSearchResult] = [:]\n\n    var siteURL: URL? {\n        get {\n            _siteURL ?? searchLanguageBarViewController?.selectedSiteURL ?? MWKDataStore.shared().primarySiteURL ?? NSURL.wmf_URLWithDefaultSiteAndCurrentLocale()\n        }\n        set { _siteURL = newValue }\n    }\n\n    var searchLanguageBarTopConstraint: NSLayoutConstraint?\n\n    // MARK: - Init\n\n    init(source: EventLoggingSource, dataStore: MWKDataStore) {\n        self.source = source\n        self.dataStore = dataStore\n        self.instrumentation = SearchInstrumentation(isEnabled: source != .editor)\n        super.init(nibName: nil, bundle: nil)\n    }\n\n    @MainActor required init?(coder: NSCoder) {\n        fatalError(\"init(coder:) has not been implemented\")\n    }\n\n    deinit {\n        searchTask?.cancel()\n        NotificationCenter.default.removeObserver(self)\n    }\n\n    // MARK: - Lifecycle\n\n    override func viewDidLoad() {\n        super.viewDidLoad()\n\n        view.addSubview(contentContainerView)\n        contentContainerView.translatesAutoresizingMaskIntoConstraints = false\n        NSLayoutConstraint.activate([\n            contentContainerView.topAnchor.constraint(equalTo: view.topAnchor),\n            contentContainerView.leadingAnchor.constraint(equalTo: view.leadingAnchor),\n            contentContainerView.trailingAnchor.constraint(equalTo: view.trailingAnchor),\n            contentContainerView.bottomAnchor.constraint(equalTo: view.bottomAnchor)\n        ])\n\n        updateLanguageBarVisibility()\n        reloadRecentSearches()\n        showRecentSearches(animated: false)\n        NotificationCenter.default.addObserver(self, selector: #selector(articleWasUpdated(_:)), name: .WMFArticleUpdated, object: nil)\n        NotificationCenter.default.addObserver(self, selector: #selector(keyboardDidHide(_:)), name: UIResponder.keyboardDidHideNotification, object: nil)\n    }\n\n    override func viewWillAppear(_ animated: Bool) {\n        super.viewWillAppear(animated)\n        updateLanguageBarVisibility()\n        reloadRecentSearches()\n        refreshSemanticSearchEntryPointIfResultsAreShown()\n    }\n\n    override func viewDidLayoutSubviews() {\n        super.viewDidLayoutSubviews()\n        let languagesBarHeight = searchLanguageBarViewController?.view.bounds.height ?? 0\n        recentSearchesViewModel.topPadding = languagesBarHeight\n        resultsViewModel.topPadding = languagesBarHeight\n        resultsViewModel.horizontalPadding = max(view.layoutMargins.left, round((view.bounds.width - view.readableContentGuide.layoutFrame.width) / 2))\n        applyScrollEdgeEffect(isLanguageBarVisible: searchLanguageBarViewController != nil, to: contentScrollViews)\n    }\n\n    // MARK: - Embedded content container\n\n    private func embedInContainer(_ vc: UIViewController, animated: Bool) {\n        if currentEmbeddedViewController === vc { return }\n\n        let oldVC = currentEmbeddedViewController\n        oldVC?.willMove(toParent: nil)\n\n        addChild(vc)\n        vc.view.translatesAutoresizingMaskIntoConstraints = false\n        contentContainerView.addSubview(vc.view)\n        NSLayoutConstraint.activate([\n            vc.view.topAnchor.constraint(equalTo: contentContainerView.topAnchor),\n            vc.view.leadingAnchor.constraint(equalTo: contentContainerView.leadingAnchor),\n            vc.view.trailingAnchor.constraint(equalTo: contentContainerView.trailingAnchor),\n            vc.view.bottomAnchor.constraint(equalTo: contentContainerView.bottomAnchor)\n        ])\n\n        let finish = {\n            oldVC?.view.removeFromSuperview()\n            oldVC?.removeFromParent()\n            vc.didMove(toParent: self)\n            self.currentEmbeddedViewController = vc\n        }\n\n        guard animated, let oldView = oldVC?.view else {\n            finish()\n            return\n        }\n\n        vc.view.alpha = 0\n        UIView.animate(withDuration: 0.2, animations: {\n            vc.view.alpha = 1\n            oldView.alpha = 0\n        }, completion: { _ in\n            oldView.alpha = 1\n            finish()\n        })\n    }\n\n    private func showSearchResults(animated: Bool) {\n        embedInContainer(resultsViewController, animated: animated)\n    }\n\n    private func showRecentSearches(animated: Bool) {\n        embedInContainer(recentSearchesViewController, animated: animated)\n    }\n\n    // MARK: - Language bar scroll edge fade\n\n    private var contentScrollViews: [UIScrollView] {\n        // Both children are SwiftUI hosting controllers; fish out their inner scroll views.\n        [resultsViewController, recentSearchesViewController].compactMap {\n            $0.view.firstDescendant(ofType: UIScrollView.self)\n        }\n    }\n\n    /// On iOS 26+ this uses the system `UIScrollEdgeEffect` which integrates natively\n    /// with Liquid Glass. On older OS versions it is a no-op.\n    private func applyScrollEdgeEffect(isLanguageBarVisible: Bool, to scrollViews: [UIScrollView]) {\n        guard #available(iOS 26, *) else { return }\n        let style: UIScrollEdgeEffect.Style = isLanguageBarVisible ? .hard : .automatic\n        for scrollView in scrollViews {\n            scrollView.topEdgeEffect.style = style\n        }\n    }\n\n    // MARK: - Language bar\n\n    // VoiceOver orders sibling views by frame origin. The content container starts at the top edge\n    // and covers the language bar, so without an explicit order the bar comes after the last result.\n    private func updateAccessibilityElements() {\n        guard let languageBarView = searchLanguageBarViewController?.view else {\n            view.accessibilityElements = nil\n            return\n        }\n        view.accessibilityElements = [languageBarView, contentContainerView]\n    }\n\n    private func setupLanguageBarViewController() -> SearchLanguagesBarViewController {\n        if let vc = self.searchLanguageBarViewController { return vc }\n        let vc = SearchLanguagesBarViewController()\n        vc.apply(theme: theme)\n        vc.delegate = self\n        self.searchLanguageBarViewController = vc\n        return vc\n    }\n\n    private func updateLanguageBarVisibility() {\n        let shouldShow = showLanguageBar && WMFSettingsDataController.shared.showSearchLanguageBar()\n\n        if shouldShow && searchLanguageBarViewController == nil {\n            let vc = setupLanguageBarViewController()\n            addChild(vc)\n            vc.view.translatesAutoresizingMaskIntoConstraints = false\n\n            let topConstraint = vc.view.topAnchor.constraint(equalTo: view.topAnchor, constant: view.safeAreaInsets.top)\n            self.searchLanguageBarTopConstraint = topConstraint\n\n            view.addSubview(vc.view)\n            NSLayoutConstraint.activate([\n                topConstraint,\n                view.safeAreaLayoutGuide.leadingAnchor.constraint(equalTo: vc.view.leadingAnchor),\n                view.safeAreaLayoutGuide.trailingAnchor.constraint(equalTo: vc.view.trailingAnchor)\n            ])\n            vc.didMove(toParent: self)\n            vc.moveScrollViewToStart()\n            vc.view.isHidden = false\n            applyScrollEdgeEffect(isLanguageBarVisible: true, to: contentScrollViews)\n            updateAccessibilityElements()\n\n        } else if !shouldShow, let vc = searchLanguageBarViewController {\n            vc.willMove(toParent: nil)\n            vc.view.removeFromSuperview()\n            vc.removeFromParent()\n            self.searchLanguageBarViewController = nil\n            self.searchLanguageBarTopConstraint = nil\n            applyScrollEdgeEffect(isLanguageBarVisible: false, to: contentScrollViews)\n            updateAccessibilityElements()\n        }\n\n        view.setNeedsLayout()\n        \n        MoreLanguagesTip.searchLanguagesBarIsVisible = shouldShow\n    }\n\n    override func viewSafeAreaInsetsDidChange() {\n        super.viewSafeAreaInsetsDidChange()\n\n        guard needsAnimateLanguageBarMovement else {\n            searchLanguageBarTopConstraint?.constant = view.safeAreaInsets.top\n            view.layoutIfNeeded()\n            return\n        }\n\n        searchLanguageBarTopConstraint?.constant = view.safeAreaInsets.top\n        UIView.animate(withDuration: 0.2) {\n            self.view.layoutIfNeeded()\n        }\n    }\n\n    // MARK: - Search\n\n    func search() {\n        search(for: searchTerm)\n    }\n\n    private func search(for searchTerm: String?) {\n        guard let siteURL else {\n            assertionFailure(\"siteURL must not be nil\")\n            return\n        }\n        self.lastSearchSiteURL = siteURL\n\n        guard let searchTerm, searchTerm.wmf_hasNonWhitespaceText else {\n            didCancelSearch()\n            return\n        }\n\n        guard (searchTerm as NSString).character(at: 0) != NSTextAttachment.character else { return }\n\n        resetSearchResults()\n        hideSemanticSearchEntryPointIfLanguageChanged(for: siteURL)\n        searchTask = Task { [weak self] in\n            await self?.performSearch(for: searchTerm, siteURL: siteURL)\n        }\n    }\n\n    private func performSearch(for searchTerm: String, siteURL: URL) async {\n        guard !Task.isCancelled else { return }\n        \n        if let project = SearchResultsMapper.project(for: siteURL) {\n            let origin: SearchInstrumentation.SearchOrigin\n            if recentSearchTermPendingInit == searchTerm {\n                origin = .recentSearch\n            } else if isDictating {\n                origin = .voice\n            } else {\n                origin = .typed\n            }\n            instrumentation.logSearchInit(searchTerm: searchTerm, project: project, origin: origin)\n        }\n        recentSearchTermPendingInit = nil\n        if let languageCode = siteURL.wmf_languageCode {\n            enrollInSemanticSearchExperimentIfNeeded(languageCode: languageCode)\n        }\n        do {\n            let outcome = try await resultsLoader.fetchResults(for: searchTerm, siteURL: siteURL)\n            guard !Task.isCancelled else { return }\n            NSUserActivity.wmf_makeActive(NSUserActivity.wmf_searchResultsActivitySearchSiteURL(siteURL, searchTerm: searchTerm))\n            displayedSearchResults = outcome\n            instrumentation.logLexicalResultsImpression(searchIDs: outcome.results.lexicalSearchIDs)\n            displaySearchResults(outcome.results, siteURL: siteURL)\n        } catch is CancellationError {\n            return\n        } catch let SearchResultsLoader.Failure.fetch(error, _) {\n            guard !Task.isCancelled, !(error as NSError).wmf_isCancelledError() else { return }\n            displaySearchError(error)\n        } catch {\n            assertionFailure(\"Unexpected search error: \\(error)\")\n        }\n    }\n\n    private lazy var fetcher = WMFSearchFetcher()\n    private lazy var resultsLoader = SearchResultsLoader(fetcher: fetcher)\n\n    func resetSearchResults() {\n        searchTask?.cancel()\n        searchTask = nil\n        fetcher.cancelAllFetches()\n        resultsViewModel.reset()\n    }\n\n    /// Searches from the editor neither enroll the reader nor show the entry point.\n    var takesPartInSemanticSearchExperiment: Bool {\n        source != .editor\n    }\n\n    /// A reader with a target wiki among their app languages gets a group when search opens.\n    private func enrollInSemanticSearchExperimentIfNeeded() {\n        guard takesPartInSemanticSearchExperiment else { return }\n        do {\n            try WMFSemanticSearchDataController.shared.enrollIfNeeded()\n        } catch {\n            DDLogError(\"Semantic search experiment assignment failed: \\(error)\")\n        }\n    }\n\n    /// A search on a target wiki gets the reader a group if they have none yet. The exposure\n    /// event goes out once per install, on the first such search.\n    private func enrollInSemanticSearchExperimentIfNeeded(languageCode: String) {\n        guard takesPartInSemanticSearchExperiment else { return }\n        let dataController = WMFSemanticSearchDataController.shared\n        do {\n            try dataController.enrollIfNeeded(languageCode: languageCode)\n            if dataController.shouldSendExposure(languageCode: languageCode) {\n                instrumentation.logExperimentExposure()\n            }\n        } catch {\n            DDLogError(\"Semantic search experiment assignment failed: \\(error)\")\n        }\n    }\n\n    func didCancelSearch() {\n        resetSearchResults()\n        resultsViewModel.hideSemanticSearchEntryPoint()\n    }\n\n    /// Programmatically trigger a search for `term` and show results \u2014 used when the caller\n    /// sets the search bar text internally without typing (e.g. NSUserActivity restoration).\n    func searchAndMakeResultsVisible(for term: String?) {\n        guard let term, term.wmf_hasNonWhitespaceText else { return }\n        searchTerm = term\n        showSearchResults(animated: false)\n        search(for: term)\n    }\n\n    // MARK: - Recent Search Saving\n\n    func saveLastSearch() {\n        guard\n            let term = displayedSearchTerm,\n            let url = displayedSiteURL,\n            let entry = MWKRecentSearchEntry(url: url, searchTerm: term)\n        else { return }\n        dataStore.recentSearchList.addEntry(entry)\n        dataStore.recentSearchList.save()\n        reloadRecentSearches()\n    }\n\n    // MARK: - Child VCs\n\n    lazy var resultsViewModel: WMFSearchResultsViewModel = makeResultsViewModel()\n\n    private lazy var resultsViewController: UIViewController = {\n        let root = WMFSearchResultsView(viewModel: resultsViewModel)\n        return UIHostingController(rootView: root)\n    }()\n\n    private lazy var recentSearchesViewController: UIViewController = {\n        let root = WMFRecentlySearchedView(viewModel: recentSearchesViewModel)\n        return UIHostingController(rootView: root)\n    }()\n\n    // MARK: - Recently Searched\n\n    private var recentSearches: MWKRecentSearchList? { dataStore.recentSearchList }\n\n    private lazy var didPressClearRecentSearches: () -> Void = { [weak self] in\n        let dialog = UIAlertController(\n            title: CommonStrings.clearRecentSearchesDialogTitle,\n            message: CommonStrings.clearRecentSearchesDialogSubtitle,\n            preferredStyle: .alert)\n        dialog.addAction(UIAlertAction(title: CommonStrings.cancelActionTitle, style: .cancel))\n        let deleteAction = UIAlertAction(title: CommonStrings.deleteAllTitle, style: .destructive) { _ in\n            self?.deleteAllRecentSearches()\n        }\n        deleteAction.accessibilityIdentifier = AccessibilityIdentifiers.Search.clearRecentSearchesConfirmButton\n        dialog.addAction(deleteAction)\n        self?.present(dialog, animated: true)\n    }\n\n    private func deleteAllRecentSearches() {\n        dataStore.recentSearchList.removeAllEntries()\n        dataStore.recentSearchList.save()\n        reloadRecentSearches()\n    }\n\n    private lazy var deleteItemAction: (Int) -> Void = { [weak self] index in\n        guard\n            let self,\n            self.recentSearches?.entries.indices.contains(index) ?? false,\n            let entry = self.recentSearches?.entries[index]\n        else { return }\n        Task {\n            self.dataStore.recentSearchList.removeEntry(entry)\n            self.dataStore.recentSearchList.save()\n            self.reloadRecentSearches()\n        }\n    }\n\n    private lazy var selectAction: (WMFRecentlySearchedViewModel.RecentSearchTerm) -> Void = { [weak self] term in\n        guard let self else { return }\n        self.recentSearchTermPendingInit = term.text\n        self.resetSearchResults()\n        if let pop = self.populateSearchBarAction {\n            pop(term.text)\n        }\n        self.searchTerm = term.text\n    }\n\n    private lazy var recentSearchesViewModel: WMFRecentlySearchedViewModel = {\n        let strings = WMFRecentlySearchedViewModel.LocalizedStrings(\n            title: CommonStrings.recentlySearchedTitle,\n            noSearches: CommonStrings.recentlySearchedEmpty,\n            clearAll: CommonStrings.clearTitle,\n            deleteActionAccessibilityLabel: CommonStrings.deleteActionTitle,\n            editButtonTitle: CommonStrings.editContextMenuTitle\n        )\n        return WMFRecentlySearchedViewModel(\n            recentSearchTerms: currentRecentSearchTerms(),\n            topPadding: 0,\n            localizedStrings: strings,\n            deleteAllAction: didPressClearRecentSearches,\n            deleteItemAction: deleteItemAction,\n            selectAction: selectAction\n        )\n    }()\n\n    private func currentRecentSearchTerms() -> [WMFRecentlySearchedViewModel.RecentSearchTerm] {\n        (recentSearches?.entries ?? []).map {\n            WMFRecentlySearchedViewModel.RecentSearchTerm(text: $0.searchTerm)\n        }\n    }\n\n    private func reloadRecentSearches() {\n        recentSearchesViewModel.recentSearchTerms = currentRecentSearchTerms()\n    }\n\n    // MARK: - Theme\n\n    override func apply(theme: Theme) {\n        super.apply(theme: theme)\n        searchBarIPadCustomizer.theme = theme\n        overrideUserInterfaceStyle = theme.isDark ? .dark : .light\n        guard viewIfLoaded != nil else { return }\n        view.backgroundColor = theme.colors.paperBackground\n        contentContainerView.backgroundColor = theme.colors.paperBackground\n        recentSearchesViewController.view.backgroundColor = theme.colors.paperBackground\n        searchLanguageBarViewController?.apply(theme: theme)\n        resultsViewController.view.backgroundColor = theme.colors.paperBackground\n    }\n}","file":"Wikipedia/Code/SearchResultsViewController.swift","kind":"class","line":9,"members":{"SearchResultsViewController":[124,131],"_siteURL":[98,98],"apply":[538,550],"applyScrollEdgeEffect":[236,244],"article":[257,261],"articleTappedAction":[31,33],"articleWasUpdated":[249,255],"contentContainerView":[86,86],"contentScrollViews":[227,234],"currentEmbeddedViewController":[87,87],"currentRecentSearchTerms":[528,532],"dataStore":[65,65],"deinit":[137,140],"deleteAllRecentSearches":[481,485],"deleteItemAction":[487,498],"didCancelSearch":[422,425],"didDismissSearchController":[622,625],"didPresentSearchController":[617,620],"didPressClearRecentSearches":[467,479],"displaySearchError":[225,237],"displaySearchResults":[85,104],"displayedSearchResults":[104,105],"displayedSearchTerm":[102,102],"displayedSiteURL":[103,103],"embedInContainer":[179,217],"enrollInSemanticSearchExperimentIfNeeded":[397,405],"eventLoggingCategory":[24,24],"eventLoggingLabel":[25,25],"expectedSearchBarText":[110,112],"fetcher":[382,382],"focusesFirstResultWhenKeyboardHides":[101,101],"hideSemanticSearchEntryPoint":[181,198],"hideSemanticSearchEntryPointIfLanguageChanged":[136,142],"instrumentation":[35,38],"isDictating":[108,109],"isShowingSearchResults":[89,91],"keyboardDidHide":[239,247],"lastSearchSiteURL":[97,97],"makeResultsViewModel":[26,83],"makeSemanticSearchEntryPointViewModel":[144,179],"needsAnimateLanguageBarMovement":[94,94],"noSearchResultsMessage":[12,12],"openInBackgroundTab":[200,223],"parentSearchControllerDelegate":[67,70],"performSearch":[347,380],"populateSearchBarAction":[50,52],"recentSearchTermPendingInit":[106,107],"recentSearches":[463,465],"recentSearchesViewController":[458,461],"recentSearchesViewModel":[510,526],"refreshSemanticSearchEntryPointIfResultsAreShown":[128,134],"reloadRecentSearches":[534,536],"resetSearchResults":[385,390],"resultsLoader":[383,383],"resultsViewController":[453,456],"resultsViewModel":[449,451],"saveLastSearch":[436,447],"saveOrUnsave":[263,280],"search":[320,324],"searchActionSubtype":[330,338],"searchAndMakeResultsVisible":[427,434],"searchBar":[307,313],"searchBarCancelButtonClicked":[303,305],"searchBarIPadCustomizer":[72,84],"searchBarSearchButtonClicked":[299,301],"searchLanguageBarTopConstraint":[122,122],"searchLanguageBarViewController":[93,93],"searchLanguagesBarViewController":[631,633],"searchResultsByArticleURL":[113,113],"searchTask":[99,99],"searchTerm":[96,96],"selectAction":[500,508],"semanticSearchHiddenToastButtonTitle":[22,24],"semanticSearchHiddenToastSubtitle":[18,20],"semanticSearchHiddenToastTitle":[14,16],"semanticSearchInfoTappedAction":[46,48],"semanticSearchSettingsTappedAction":[42,44],"semanticSearchTappedAction":[40,40],"setupLanguageBarViewController":[258,265],"share":[288,293],"showLanguageBar":[54,60],"showRecentSearches":[223,225],"showSearchResults":[219,221],"siteURL":[115,120],"source":[62,64],"takesPartInSemanticSearchExperiment":[392,395],"unsave":[282,286],"updateAccessibilityElements":[246,256],"updateLanguageBarVisibility":[267,303],"updateSearchResults":[556,588],"updateSemanticSearchEntryPoint":[106,126],"viewDidLayoutSubviews":[170,177],"viewDidLoad":[142,161],"viewSafeAreaInsetsDidChange":[305,318],"viewWillAppear":[163,168],"willDismissSearchController":[609,615],"willPresentSearchController":[599,607]},"supers":["ThemeableViewController","WMFNavigationBarConfiguring","MEPEventsProviding","ShareableArticlesProvider","UISearchResultsUpdating","UISearchControllerDelegate","SearchLanguagesBarViewControllerDelegate","UISearchBarDelegate"]},"SearchViewController":{"alsoIn":["Wikipedia/Code/SearchViewController.swift","Wikipedia/Code/SearchViewController.swift","Wikipedia/Code/SearchViewController.swift"],"appearsIn":[["index","h-screens","Screens \u00b7 how the user moves"],["search","h-classes","Logic \u00b7 class diagram"],["search","h-widgets","Screen \u00b7 view composition"]],"code":"/// Standalone view controller for searching Wikipedia articles. Designed to be used within a navigation controller, as its search bar leans on navigationItem.searchController behavior.\nclass SearchViewController: ThemeableViewController, WMFNavigationBarConfiguring, MEPEventsProviding, ShareableArticlesProvider {\n    \n    let source: SearchResultsViewController.EventLoggingSource\n\n    // MARK: - MEP / Hint\n\n    var eventLoggingCategory: EventCategoryMEP { .history }\n    var eventLoggingLabel: EventLabelMEP? { nil }\n\n    // MARK: - Dependencies\n\n    @objc var dataStore: MWKDataStore?\n\n    // MARK: - Private state\n\n    private var isSearchActive = false\n    /// Where the pushed article was opened from. The reader returns from it to the same search.\n    private enum PushedArticleSource {\n        /// A search result. The keyboard comes back on return.\n        case searchResults\n        /// The semantic search sheet. The sheet comes back on return.\n        case semanticSearchSheet\n    }\n\n    /// Set while an article opened from the search is pushed, so the search stays active under it.\n    private var pushedArticleSource: PushedArticleSource?\n    private var cancellables = Set<AnyCancellable>()\n    \n    \n    // MARK: - Public configuration (set before pushing)\n\n    /// Hides history display entirely\n    var shouldHideHistory: Bool = false\n\n    /// Forwarded to the container. Default `true`.\n    var showLanguageBar: Bool = true\n\n    /// Forwarded to the container to scope searches to a specific wiki.\n    var siteURL: URL?\n\n    /// If set, the search bar is pre-populated with this term and a search is triggered on appear.\n    var prefilledSearchTerm: String?\n\n    /// Override the default article-push behavior. If nil, uses `LinkCoordinator`.\n    var articleTappedAction: ((URL) -> Void)?\n    \n    /// Computed property to help determine if this is a root tab view or not. If true, profile and tabs navigation buttons are added and navigation bar title alignment is adjusted.\n    private var isRootTabView: Bool {\n        guard tabBarController != nil else {\n            return false\n        }\n        \n        guard let navigationController,\n              navigationController.viewControllers.count > 0,\n              navigationController.viewControllers[0] == self else {\n            return false\n        }\n        \n        return true\n    }\n\n    // MARK: - Coordinators\n\n    private var semanticSearchResultsCoordinator: SemanticSearchResultsCoordinator?\n    private var semanticSearchInfoCoordinator: SemanticSearchInfoCoordinator?\n    private var _yirCoordinator: YearInReviewCoordinator?\n    private var yirCoordinator: YearInReviewCoordinator? {\n        guard let navigationController, let yirDataController, let dataStore else { return nil }\n        if let existing = _yirCoordinator { return existing }\n        _yirCoordinator = YearInReviewCoordinator(\n            navigationController: navigationController,\n            theme: theme,\n            dataStore: dataStore,\n            dataController: yirDataController\n        )\n        _yirCoordinator?.badgeDelegate = self\n        return _yirCoordinator\n    }\n\n    private var _profileCoordinator: ProfileCoordinator?\n    private var profileCoordinator: ProfileCoordinator? {\n        guard let navigationController, let yirCoordinator, let dataStore else { return nil }\n        if let existing = _profileCoordinator { return existing }\n        _profileCoordinator = ProfileCoordinator(\n            navigationController: navigationController,\n            theme: theme,\n            dataStore: dataStore,\n            donateSouce: .searchProfile,\n            logoutDelegate: self,\n            sourcePage: .search,\n            yirCoordinator: yirCoordinator\n        )\n        _profileCoordinator?.badgeDelegate = self\n        return _profileCoordinator\n    }\n\n    private lazy var tabsCoordinator: TabsOverviewCoordinator? = { [weak self] in\n        guard let self, let nav = navigationController, let dataStore else { return nil }\n        return TabsOverviewCoordinator(navigationController: nav, theme: theme, dataStore: dataStore)\n    }()\n\n    private var yirDataController: WMFYearInReviewDataController? { try? WMFYearInReviewDataController() }\n\n    // MARK: - Delete button (shown leading when history is visible)\n\n    private lazy var deleteButton: UIBarButtonItem = {\n        UIBarButtonItem(\n            title: CommonStrings.clearTitle,\n            style: .plain,\n            target: self,\n            action: #selector(deleteButtonPressed(_:))\n        )\n    }()\n\n    // MARK: - Search results container\n\n    lazy var searchResultsVC: SearchResultsViewController = {\n        let vc = SearchResultsViewController(source: source, dataStore: dataStore ?? MWKDataStore.shared())\n        vc.apply(theme: theme)\n        vc.parentSearchControllerDelegate = self\n        vc.populateSearchBarAction = { [weak self] searchTerm in\n            self?.navigationItem.searchController?.searchBar.text = searchTerm\n            self?.navigationItem.searchController?.searchBar.becomeFirstResponder()\n        }\n        vc.semanticSearchTappedAction = { [weak self] query, project in\n            self?.showSemanticSearchResults(query: query, project: project)\n        }\n        vc.semanticSearchSettingsTappedAction = { [weak self] in\n            self?.showSearchSettings()\n        }\n        vc.semanticSearchInfoTappedAction = { [weak self] languageCode in\n            self?.showSemanticSearchInfo(languageCode: languageCode)\n        }\n        vc.articleTappedAction = { [weak self] articleURL, needsNewTab in\n            guard let self, let dataStore, let navVC = navigationController else { return }\n            \n            if let customAction = self.articleTappedAction {\n                customAction(articleURL)\n            } else {\n                pushedArticleSource = .searchResults\n                let coordinator = LinkCoordinator(\n                    navigationController: navVC,\n                    url: articleURL,\n                    dataStore: dataStore,\n                    theme: theme,\n                    articleSource: .search,\n                    tabConfig: needsNewTab ? .appendArticleAndAssignNewTabAndSetToCurrent : .appendArticleAndAssignCurrentTab\n                )\n                if !coordinator.start() {\n                    navigate(to: articleURL)\n                }\n            }\n            \n        }\n        return vc\n    }()\n\n    // MARK: - Semantic search results\n\n    private func showSemanticSearchResults(query: String, project: WMFProject) {\n        guard let navigationController else { return }\n\n        navigationItem.searchController?.searchBar.resignFirstResponder()\n\n        let coordinator = SemanticSearchResultsCoordinator(\n            navigationController: navigationController,\n            query: query,\n            project: project,\n            instrumentation: searchResultsVC.instrumentation,\n            didSelectResult: { [weak self] result, searchID, needsFeedback in\n                self?.openSemanticSearchResult(result, project: project, searchID: searchID, needsFeedback: needsFeedback)\n            }\n        )\n\n        semanticSearchResultsCoordinator = coordinator\n        coordinator.start()\n    }\n\n    private func showSearchSettings() {\n        guard let navigationController else { return }\n\n        navigationItem.searchController?.searchBar.resignFirstResponder()\n        SearchSettingsCoordinator(navigationController: navigationController).start()\n    }\n\n    /// Opens the article at the section of the passage and highlights the passage in it.\n    private func openSemanticSearchResult(_ result: WMFSemanticSearchResult, project: WMFProject, searchID: String?, needsFeedback: Bool) {\n        guard let dataStore, let navigationController,\n              let siteURL = project.siteURL,\n              var articleURL = siteURL.wmf_URL(withTitle: result.title)?.wmf_URL(withOptionalFragment: result.sectionTitle.map(Self.sectionAnchor))\n        else { return }\n\n        articleURL.wmf_languageVariantCode = project.languageVariantCode\n\n        let coordinator = ArticleCoordinator(\n            navigationController: navigationController,\n            articleURL: articleURL,\n            dataStore: dataStore,\n            theme: theme,\n            source: .search,\n            semanticSearchPassages: WMFSemanticSearchSnippet.highlightedTexts(html: result.snippetHTML),\n            semanticSearchID: searchID,\n            semanticSearchInstrumentation: searchResultsVC.instrumentation,\n            needsSemanticSearchFeedback: needsFeedback\n        )\n        pushedArticleSource = .semanticSearchSheet\n        if !coordinator.start() {\n            navigate(to: articleURL)\n        }\n    }\n\n    /// The id MediaWiki gives the heading of a section: the title with underscores for spaces.\n    private static func sectionAnchor(for sectionTitle: String) -> String {\n        sectionTitle.replacingOccurrences(of: \" \", with: \"_\")\n    }\n\n    // MARK: - Semantic search info\n\n    private func showSemanticSearchInfo(languageCode: String) {\n        guard let navigationController else { return }\n\n        let coordinator = SemanticSearchInfoCoordinator(navigationController: navigationController, languageCode: languageCode, instrumentation: searchResultsVC.instrumentation)\n        semanticSearchInfoCoordinator = coordinator\n        coordinator.start()\n    }\n\n    // MARK: - History\n\n    lazy var historyDataController: WMFHistoryDataController = {\n        let recordsProvider: WMFHistoryDataController.RecordsProvider = { [weak self] in\n            guard let self, let dataStore else { return [] }\n\n            let request: NSFetchRequest<WMFArticle> = WMFArticle.fetchRequest()\n            request.predicate = NSPredicate(format: \"viewedDate != NULL\")\n            request.sortDescriptors = [\n                NSSortDescriptor(keyPath: \\WMFArticle.viewedDateWithoutTime, ascending: false),\n                NSSortDescriptor(keyPath: \\WMFArticle.viewedDate, ascending: false)\n            ]\n            request.fetchLimit = 1000\n\n            do {\n                return try dataStore.viewContext.fetch(request).compactMap { article -> HistoryRecord? in\n                    guard let viewedDate = article.viewedDate, let pageID = article.pageID else { return nil }\n                    let thumbnailWidth = ImageUtils.listThumbnailWidth()\n                    return HistoryRecord(\n                        id: Int(truncating: pageID),\n                        title: article.displayTitle ?? article.displayTitleHTML,\n                        descriptionOrSnippet: article.capitalizedWikidataDescriptionOrSnippet,\n                        shortDescription: article.snippet,\n                        articleURL: article.url,\n                        imageURL: article.imageURL(forWidth: thumbnailWidth)?.absoluteString,\n                        viewedDate: viewedDate,\n                        isSaved: article.isSaved,\n                        snippet: article.snippet,\n                        variant: article.variant\n                    )\n                }\n            } catch {\n                DDLogError(\"Error fetching history: \\(error)\")\n                return []\n            }\n        }\n\n        let deleteRecordAction: WMFHistoryDataController.DeleteRecordAction = { [weak self] historyItem in\n            guard let self, let dataStore else { return }\n            guard let databaseKey = historyItem.url?.wmf_databaseKey else { return }\n            let request: NSFetchRequest<WMFArticle> = WMFArticle.fetchRequest()\n            request.predicate = NSPredicate(format: \"key == %@\", databaseKey)\n            request.fetchLimit = 1\n            do {\n                if let article = try dataStore.viewContext.fetch(request).first {\n                    try article.removeFromReadHistory()\n                }\n            } catch {\n                showError(error)\n            }\n\n            guard let title = historyItem.url?.wmf_title,\n                  let languageCode = historyItem.url?.wmf_languageCode else { return }\n            let project = WMFProject.wikipedia(WMFLanguage(languageCode: languageCode, languageVariantCode: historyItem.variant))\n            Task {\n                do {\n                    let dc = try WMFPageViewsDataController()\n                    try await dc.deletePageView(title: title, namespaceID: 0, project: project)\n                } catch {\n                    DDLogError(\"Failure deleting WMFData WMFPageViews: \\(error)\")\n                }\n            }\n        }\n\n        let saveArticleAction: WMFHistoryDataController.SaveRecordAction = { [weak self] historyItem in\n            guard let self, let dataStore, let articleURL = historyItem.url else { return }\n            dataStore.savedPageList.addSavedPage(with: articleURL)\n            historyItem.isSaved = true\n        }\n\n        let unsaveArticleAction: WMFHistoryDataController.UnsaveRecordAction = { [weak self] historyItem in\n            guard let self, let dataStore, let articleURL = historyItem.url else { return }\n            dataStore.savedPageList.removeEntry(with: articleURL)\n            historyItem.isSaved = false\n        }\n\n        let dc = WMFHistoryDataController(recordsProvider: recordsProvider)\n        dc.deleteRecordAction = deleteRecordAction\n        dc.saveRecordAction = saveArticleAction\n        dc.unsaveRecordAction = unsaveArticleAction\n        return dc\n    }()\n\n    lazy var historyViewModel: WMFHistoryViewModel = {\n        let strings = WMFHistoryViewModel.LocalizedStrings(\n            emptyViewTitle: CommonStrings.emptyNoHistoryTitle,\n            emptyViewSubtitle: CommonStrings.emptyNoHistorySubtitle,\n            todayTitle: CommonStrings.todayTitle,\n            yesterdayTitle: CommonStrings.yesterdayTitle,\n            openArticleActionTitle: CommonStrings.articleTabsOpen,\n            saveForLaterActionTitle: CommonStrings.saveTitle,\n            unsaveActionTitle: CommonStrings.unsaveTitle,\n            shareActionTitle: CommonStrings.shareMenuTitle,\n            deleteSwipeActionLabel: CommonStrings.deleteActionTitle,\n            historyHeaderTitle: CommonStrings.historyTabTitle\n        )\n        let vm = WMFHistoryViewModel(\n            emptyViewImage: UIImage(named: \"history-blank\"),\n            localizedStrings: strings,\n            historyDataController: historyDataController\n        )\n        vm.onTapArticle = { [weak self] historyItem in\n            self?.tappedHistoryArticle(historyItem)\n        }\n        vm.shareRecordAction = { [weak self] frame, historyItem in\n            self?.share(item: historyItem, frame: frame)\n        }\n        return vm\n    }()\n\n    private func tappedHistoryArticle(_ item: HistoryItem) {\n        guard let articleURL = item.url, let dataStore, let navVC = navigationController else { return }\n        let coordinator = ArticleCoordinator(navigationController: navVC, articleURL: articleURL, dataStore: dataStore, theme: theme, source: .history)\n        coordinator.start()\n    }\n\n    private func share(item: HistoryItem, frame: CGRect?) {\n        guard let dataStore, let url = item.url else { return }\n        let article = dataStore.fetchArticle(with: url)\n        let sourceRect = frame.map { view.convert($0, from: nil) }\n        _ = share(article: article, articleURL: url, dataStore: dataStore, theme: theme, eventLoggingCategory: eventLoggingCategory, eventLoggingLabel: eventLoggingLabel, sourceView: view, sourceRect: sourceRect)\n    }\n\n    lazy var historyViewController: WMFHistoryHostingController = {\n        WMFHistoryHostingController(rootView: WMFHistoryView(viewModel: historyViewModel))\n    }()\n\n    // MARK: - Lifecycle\n    \n    @objc init(source: SearchResultsViewController.EventLoggingSource) {\n        self.source = source\n        super.init(nibName: nil, bundle: nil)\n    }\n    \n    @MainActor required init?(coder: NSCoder) {\n        fatalError(\"init(coder:) has not been implemented\")\n    }\n    \n    override func viewDidLoad() {\n        super.viewDidLoad()\n        view.accessibilityIdentifier = AccessibilityIdentifiers.Search.view\n        \n        // Apply configuration properties to the container now that it's initialized\n        searchResultsVC.showLanguageBar = showLanguageBar\n        if let siteURL { searchResultsVC.siteURL = siteURL }\n        embedHistoryIfNeeded()\n        \n        registerForTraitChanges([UITraitPreferredContentSizeCategory.self, UITraitHorizontalSizeClass.self, UITraitVerticalSizeClass.self]) { [weak self] (viewController: Self, previousTraitCollection: UITraitCollection) in\n            guard let self else { return }\n            if #available(iOS 18, *) {\n                if UIDevice.current.userInterfaceIdiom == .pad {\n                    if previousTraitCollection.horizontalSizeClass != traitCollection.horizontalSizeClass {\n                        configureNavigationBar()\n                    }\n                }\n            }\n        }\n    }\n\n    override func viewWillAppear(_ animated: Bool) {\n        super.viewWillAppear(animated)\n        configureNavigationBar()\n    }\n    \n    override func viewWillDisappear(_ animated: Bool) {\n        super.viewWillDisappear(animated)\n\n        // Keep the search active under the pushed article, so the reader returns to it.\n        if pushedArticleSource == nil {\n            if navigationItem.searchController?.isActive == true {\n                navigationItem.searchController?.isActive = false\n            }\n            isSearchActive = false\n            navigationItem.searchController = nil\n            navigationItem.title = nil\n        }\n        hideCustomLeadingLargeTitleLabel()\n    }\n\n    override func viewDidAppear(_ animated: Bool) {\n        super.viewDidAppear(animated)\n        NSUserActivity.wmf_makeActive(NSUserActivity.wmf_searchView())\n\n        let returningFromArticle = pushedArticleSource != nil\n        switch pushedArticleSource {\n        case .searchResults:\n            // On iPad the search field can't become first responder yet in viewDidAppear, so wait a turn.\n            Task { @MainActor [weak self] in\n                self?.navigationItem.searchController?.searchBar.becomeFirstResponder()\n            }\n        case .semanticSearchSheet:\n            semanticSearchResultsCoordinator?.restore()\n        case nil:\n            break\n        }\n        pushedArticleSource = nil\n\n        if isRootTabView {\n            ArticleTabsFunnel.shared.logIconImpression(interface: .search, project: nil)\n        } else {\n            // Returning from an article keeps the reader's own search instead of the prefilled one.\n            if !returningFromArticle, let term = self.prefilledSearchTerm {\n                self.navigationItem.searchController?.searchBar.text = term\n                self.searchResultsVC.searchAndMakeResultsVisible(for: term)\n                self.navigationItem.searchController?.searchBar.becomeFirstResponder()\n            }\n        }\n        \n    }\n    \n    override func viewDidLayoutSubviews() {\n        super.viewDidLayoutSubviews()\n        \n        if !shouldHideHistory {\n            let topSafeAreaHeight = view.safeAreaInsets.top\n            let bottomSafeAreaHeight = view.safeAreaInsets.bottom\n            historyViewModel.topPadding = topSafeAreaHeight\n            historyViewModel.bottomPadding = bottomSafeAreaHeight\n        }\n    }\n\n    // MARK: - Navigation Bar\n\n    private func configureNavigationBar() {\n        let alignment: WMFNavigationBarTitleConfig.Alignment\n        if isRootTabView {\n            alignment = isSearchActive ? .hidden : .customLeadingLarge\n        } else {\n            alignment = .centerCompact\n        }\n        let titleConfig = WMFNavigationBarTitleConfig(title: CommonStrings.searchTitle, customView: nil, alignment: alignment)\n\n        var profileButtonConfig: WMFNavigationBarProfileButtonConfig? = nil\n        var tabsButtonConfig: WMFNavigationBarTabsButtonConfig? = nil\n        \n        if let dataStore,\n           isRootTabView {\n            profileButtonConfig = self.profileButtonConfig(target: self, action: #selector(userDidTapProfile), dataStore: dataStore, yirDataController: yirDataController)\n\n            let historyClearButton: UIBarButtonItem? = isSearchActive ? nil : deleteButton\n            tabsButtonConfig = self.tabsButtonConfig(target: self, action: #selector(userDidTapTabs), dataStore: dataStore, leadingBarButtonItem: historyClearButton)\n        }\n\n        let searchConfig = WMFNavigationBarSearchConfig(\n            searchResultsController: searchResultsVC,\n            searchControllerDelegate: searchResultsVC,\n            searchResultsUpdater: searchResultsVC,\n            searchBarDelegate: searchResultsVC,\n            searchBarPlaceholder: CommonStrings.searchBarPlaceholder,\n            showsScopeBar: false,\n            scopeButtonTitles: nil\n        )\n\n        configureNavigationBar(\n            titleConfig: titleConfig,\n            backButtonConfig: nil,\n            closeButtonConfig: nil,\n            profileButtonConfig: profileButtonConfig,\n            tabsButtonConfig: tabsButtonConfig,\n            searchBarConfig: searchConfig,\n            hideNavigationBarOnScroll: !isSearchActive && !isRootTabView\n        )\n        \n        if !isRootTabView, !shouldHideHistory {\n            let historyClearButton: UIBarButtonItem? = isSearchActive ? nil : deleteButton\n            navigationItem.rightBarButtonItem = historyClearButton\n        }\n    }\n\n    @MainActor\n    private func refreshHistoryClearButtonState() {\n        let enabled = !isSearchActive && !historyViewModel.isEmpty\n        deleteButton.isEnabled = enabled\n        configureNavigationBar()\n    }\n\n    private func updateProfileButton() {\n        guard let dataStore else { return }\n        let config = self.profileButtonConfig(target: self, action: #selector(userDidTapProfile), dataStore: dataStore, yirDataController: yirDataController)\n        updateNavigationBarProfileButton(needsBadge: config.needsBadge, needsBadgeLabel: CommonStrings.profileButtonBadgeTitle, noBadgeLabel: CommonStrings.profileButtonTitle)\n    }\n\n    @objc private func userDidTapProfile() {\n        guard let dataStore else { return }\n        guard let languageCode = dataStore.languageLinkController.appLanguage?.languageCode,\n              let metricsID = DonateCoordinator.metricsID(for: .searchProfile, languageCode: languageCode) else { return }\n        DonateFunnel.shared.logSearchProfile(metricsID: metricsID)\n        profileCoordinator?.start()\n    }\n\n    @objc private func userDidTapTabs() {\n        tabsCoordinator?.start()\n        ArticleTabsFunnel.shared.logIconClick(interface: .search, project: nil)\n    }\n\n    @objc private func deleteButtonPressed(_ sender: UIBarButtonItem) {\n        let alertController = UIAlertController(\n            title: WMFLocalizedString(\"history-clear-confirmation-heading\", value: \"Are you sure you want to delete all your recent items?\", comment: \"Heading text of delete all confirmation dialog\"),\n            message: nil,\n            preferredStyle: .actionSheet\n        )\n        alertController.addAction(UIAlertAction(\n            title: WMFLocalizedString(\"history-clear-delete-all\", value: \"Yes, delete all\", comment: \"Button text for confirming delete all action\"),\n            style: .destructive) { [weak self] _ in self?.deleteAll() }\n        )\n        alertController.addAction(UIAlertAction(title: CommonStrings.cancelActionTitle, style: .cancel))\n        alertController.popoverPresentationController?.barButtonItem = sender\n        alertController.popoverPresentationController?.permittedArrowDirections = .any\n        present(alertController, animated: true)\n    }\n\n    private func deleteAll() {\n        guard let dataStore else { return }\n        do {\n            try dataStore.viewContext.clearReadHistory()\n            historyViewModel.sections = []\n        } catch {\n            showError(error)\n        }\n        Task {\n            do {\n                let dc = try WMFPageViewsDataController()\n                try await dc.deleteAllPageViewsCategoriesAndTopics()\n            } catch {\n                DDLogError(\"Failure deleting WMFData WMFPageViews: \\(error)\")\n            }\n            do {\n                try await WMFYearInReviewDataController().deletePersonalizedData(for: .readingHistory)\n            } catch {\n                DDLogError(\"Failure deleting Year in Review reading data: \\(error)\")\n            }\n        }\n    }\n\n    // MARK: - Public interface for WMFAppViewController\n\n    @objc func makeSearchBarBecomeFirstResponder() {\n        guard !(navigationItem.searchController?.searchBar.isFirstResponder ?? false) else { return }\n        navigationItem.searchController?.searchBar.becomeFirstResponder()\n    }\n\n    @objc func searchAndMakeResultsVisibleForSearchTerm(_ term: String?, animated: Bool) {\n        navigationItem.searchController?.isActive = true\n        navigationItem.searchController?.searchBar.text = term\n        searchResultsVC.searchAndMakeResultsVisible(for: term)\n        navigationItem.searchController?.searchBar.becomeFirstResponder()\n    }\n\n    // MARK: - History\n    \n    private func embedHistoryIfNeeded() {\n        \n        guard !shouldHideHistory else {\n            return\n        }\n        \n        // Embed history as the background view (always present, shown/hidden via alpha or isHidden)\n        addChild(historyViewController)\n        historyViewController.view.translatesAutoresizingMaskIntoConstraints = false\n        view.addSubview(historyViewController.view)\n        NSLayoutConstraint.activate([\n            historyViewController.view.topAnchor.constraint(equalTo: view.topAnchor),\n            historyViewController.view.leadingAnchor.constraint(equalTo: view.leadingAnchor),\n            historyViewController.view.trailingAnchor.constraint(equalTo: view.trailingAnchor),\n            historyViewController.view.bottomAnchor.constraint(equalTo: view.bottomAnchor)\n        ])\n        historyViewController.disableContentInsetAdjustments()\n        historyViewController.didMove(toParent: self)\n\n        historyViewModel.$isEmpty\n            .receive(on: RunLoop.main)\n            .sink { [weak self] _ in\n                Task { @MainActor in self?.refreshHistoryClearButtonState() }\n            }\n            .store(in: &cancellables)\n    }\n\n    // MARK: - Theme\n\n    override func apply(theme: Theme) {\n        super.apply(theme: theme)\n        guard viewIfLoaded != nil else { return }\n        view.backgroundColor = theme.colors.paperBackground\n        if !shouldHideHistory {\n            historyViewController.view.backgroundColor = theme.colors.paperBackground\n        }\n        \n        searchResultsVC.apply(theme: theme)\n        \n        if isRootTabView {\n            updateProfileButton()\n            profileCoordinator?.theme = theme\n            yirCoordinator?.theme = theme\n            themeNavigationBarCustomLeadingLargeTitle()\n        }\n        \n    }\n}","file":"Wikipedia/Code/SearchViewController.swift","kind":"class","line":10,"members":{"SearchViewController":[364,369],"_profileCoordinator":[90,90],"_yirCoordinator":[76,76],"apply":[614,633],"articleTappedAction":[54,55],"cancellables":[37,37],"configureNavigationBar":[458,504],"dataStore":[20,22],"deleteAll":[548,569],"deleteButton":[114,123],"deleteButtonPressed":[532,546],"didDismissSearchController":[658,669],"didPresentSearchController":[650,652],"didTapLogout":[675,680],"embedHistoryIfNeeded":[585,612],"eventLoggingCategory":[15,17],"eventLoggingLabel":[18,18],"historyDataController":[237,318],"historyViewController":[360,362],"historyViewModel":[320,345],"isRootTabView":[57,70],"isSearchActive":[24,26],"makeSearchBarBecomeFirstResponder":[571,576],"openSemanticSearchResult":[196,220],"prefilledSearchTerm":[51,52],"profileCoordinator":[91,105],"pushedArticleSource":[35,36],"refreshHistoryClearButtonState":[506,511],"searchAndMakeResultsVisibleForSearchTerm":[578,583],"searchResultsVC":[125,166],"sectionAnchor":[222,225],"semanticSearchInfoCoordinator":[75,75],"semanticSearchResultsCoordinator":[72,74],"share":[353,358],"shouldHideHistory":[40,43],"showLanguageBar":[45,46],"showSearchSettings":[189,194],"showSemanticSearchInfo":[227,235],"showSemanticSearchResults":[168,187],"siteURL":[48,49],"source":[13,13],"tabsCoordinator":[107,110],"tappedHistoryArticle":[347,351],"updateProfileButton":[513,517],"updateYIRBadgeVisibility":[686,688],"userDidTapProfile":[519,525],"userDidTapTabs":[527,530],"viewDidAppear":[416,445],"viewDidLayoutSubviews":[447,456],"viewDidLoad":[375,394],"viewWillAppear":[396,399],"viewWillDisappear":[401,414],"willDismissSearchController":[654,656],"willPresentSearchController":[639,648],"yirCoordinator":[77,88],"yirDataController":[112,112]},"shot":"shots/code/SearchViewController.jpg","supers":["ThemeableViewController","WMFNavigationBarConfiguring","MEPEventsProviding","ShareableArticlesProvider","UISearchControllerDelegate","LogoutCoordinatorDelegate","YearInReviewBadgeDelegate"]},"SemanticSearchResultsCoordinator":{"alsoIn":["Wikipedia/Code/SemanticSearchResultsCoordinator.swift","Wikipedia/Code/SemanticSearchResultsCoordinator.swift","Wikipedia/Code/SemanticSearchResultsCoordinator.swift"],"appearsIn":[["search","h-classes","Logic \u00b7 class diagram"]],"code":"/// Presents the sheet of passages found inside articles for a search query.\nfinal class SemanticSearchResultsCoordinator: NSObject, Coordinator {\n\n    let navigationController: UINavigationController\n\n    private let query: String\n    private let project: WMFProject\n    private let instrumentation: SearchInstrumentation\n    /// The id is the search id of the request that gave the result, for the instrumentation. The flag\n    /// tells whether the article should ask for feedback: the reader ignored the prompt in the sheet.\n    private let didSelectResult: @MainActor @Sendable (WMFSemanticSearchResult, String?, Bool) -> Void\n\n    private var viewModel: WMFSemanticSearchResultsViewModel?\n    /// Kept after the sheet is dismissed to open an article, so `restore()` can show the same sheet again.\n    private var sheetNavigationController: UINavigationController?\n    private var selectedDetentIdentifier: UISheetPresentationController.Detent.Identifier?\n\n    init(\n        navigationController: UINavigationController,\n        query: String,\n        project: WMFProject,\n        instrumentation: SearchInstrumentation,\n        didSelectResult: @escaping @MainActor @Sendable (WMFSemanticSearchResult, String?, Bool) -> Void\n    ) {\n        self.navigationController = navigationController\n        self.query = query\n        self.project = project\n        self.instrumentation = instrumentation\n        self.didSelectResult = didSelectResult\n    }\n\n    @discardableResult\n    func start() -> Bool {\n        let viewModel = WMFSemanticSearchResultsViewModel(\n            query: query,\n            project: project,\n            readInArticleAction: { [weak self] result in\n                self?.open(result)\n            },\n            closeAction: { [weak self] in\n                self?.close()\n            },\n            feedbackAction: { [weak self] rating, text in\n                guard let self else { return }\n                self.instrumentation.logFeedbackSubmit(placement: .sheet, rating: rating, text: text, searchID: self.viewModel?.searchID)\n            },\n            feedbackTextFieldFocusAction: { [weak self] in\n                self?.expandSheet()\n            }\n        )\n\n        let hostingController = WMFSemanticSearchResultsHostingController(viewModel: viewModel)\n        let sheetNavigationController = WMFComponentNavigationController(\n            rootViewController: hostingController,\n            modalPresentationStyle: .pageSheet\n        )\n\n        viewModel.loggingDelegate = self\n        viewModel.feedbackPromptDelegate = self\n        self.viewModel = viewModel\n        self.sheetNavigationController = sheetNavigationController\n\n        viewModel.load()\n        present(sheetNavigationController)\n        return true\n    }\n\n    /// Presents the sheet again as the reader left it before opening an article from it.\n    func restore() {\n        guard let sheetNavigationController, sheetNavigationController.presentingViewController == nil else { return }\n\n        present(sheetNavigationController)\n        viewModel?.logImpressionIfLoaded()\n    }\n\n    private func present(_ sheetNavigationController: UINavigationController) {\n        // Each presentation gets a new sheet presentation controller, so configure it every time.\n        if let sheet = sheetNavigationController.sheetPresentationController {\n            sheet.detents = [.medium(), .large()]\n            sheet.selectedDetentIdentifier = selectedDetentIdentifier\n            sheet.prefersGrabberVisible = true\n            sheet.delegate = self\n        }\n\n        let presenter = navigationController.presentedViewController ?? navigationController\n        presenter.view.endEditing(true)\n        presenter.present(sheetNavigationController, animated: true)\n    }\n\n    private func open(_ result: WMFSemanticSearchResult) {\n        viewModel?.cancel()\n        selectedDetentIdentifier = sheetNavigationController?.sheetPresentationController?.selectedDetentIdentifier\n        let searchID = viewModel?.searchID\n        let isFeedbackIgnored = viewModel?.handOffFeedbackIfIgnored() ?? false\n        let needsFeedback = isFeedbackIgnored && instrumentation.canShowFeedbackPrompt(placement: .article)\n        sheetNavigationController?.dismiss(animated: true) { [weak self] in\n            self?.didSelectResult(result, searchID, needsFeedback)\n        }\n    }\n\n    /// At the medium detent the keyboard leaves little room to type and scroll.\n    private func expandSheet() {\n        guard let sheet = sheetNavigationController?.sheetPresentationController,\n              sheet.selectedDetentIdentifier != .large else { return }\n\n        sheet.animateChanges {\n            sheet.selectedDetentIdentifier = .large\n        }\n    }\n\n    /// The reader tapped the close button.\n    private func close() {\n        logClose()\n        dismiss()\n    }\n\n    private func dismiss() {\n        viewModel?.cancel()\n        sheetNavigationController?.dismiss(animated: true)\n        sheetNavigationController = nil\n    }\n\n    private func logClose() {\n        instrumentation.logResultsClose()\n    }\n}","file":"Wikipedia/Code/SemanticSearchResultsCoordinator.swift","kind":"class","line":5,"members":{"SemanticSearchResultsCoordinator":[22,34],"canShowSheetFeedbackPrompt":[160,162],"close":[115,119],"didSelectResult":[13,15],"dismiss":[121,125],"expandSheet":[105,113],"instrumentation":[12,12],"logClose":[127,129],"logEmptyResultsImpression":[149,151],"logResultTap":[153,155],"logResultsImpression":[145,147],"navigationController":[8,8],"open":[94,103],"present":[80,92],"presentationControllerDidDismiss":[134,139],"project":[11,11],"query":[10,10],"restore":[72,78],"selectedDetentIdentifier":[20,20],"sheetFeedbackPromptDidAppear":[164,166],"sheetNavigationController":[18,19],"start":[36,70],"viewModel":[17,17]},"supers":["NSObject","Coordinator","UISheetPresentationControllerDelegate","WMFSemanticSearchResultsLoggingDelegate","WMFSemanticSearchFeedbackPromptDelegate"]},"ShareableArticlesProvider":{"alsoIn":["Wikipedia/Code/ShareActivityController.swift"],"code":"protocol ShareableArticlesProvider: NSObjectProtocol {\n}","file":"Wikipedia/Code/ShareActivityController.swift","kind":"protocol","line":34,"members":{"createAndPresentShareActivityController":[62,98],"share":[38,60]},"supers":["NSObjectProtocol"]},"Themeable":{"code":"@objc(WMFThemeable)\npublic protocol Themeable: AnyObject {\n    @objc(applyTheme:)\n    func apply(theme: Theme) // this might be better as a var theme: Theme { get set } - common VC superclasses could check for viewIfLoaded and call an update method in the setter. This would elminate the need for the viewIfLoaded logic in every applyTheme:\n}","file":"WMF Framework/Theme.swift","kind":"protocol","line":1022,"members":{"apply":[1024,1025]},"supers":["AnyObject"]},"ThemeableViewController":{"alsoIn":["Wikipedia/Code/ArticleViewController.swift","Wikipedia/Code/ViewController+ArticleErrorHandling.swift"],"code":"class ThemeableViewController: UIViewController, Themeable {\n    var theme: Theme = Theme.standard\n    \n    func apply(theme: Theme) {\n        self.theme = theme\n    }\n    \n    override func viewDidLoad() {\n        super.viewDidLoad()\n        apply(theme: theme)\n    }\n}","file":"Wikipedia/Code/ThemeableViewController.swift","kind":"class","line":3,"members":{"apply":[6,8],"articleHorizontalMargin":[1795,1806],"articleMargins":[1789,1793],"presentArticleErrorRecovery":[5,20],"theme":[4,4],"viewDidLoad":[10,13]},"supers":["UIViewController","Themeable"]},"UIViewController":{"alsoIn":["Wikipedia/Code/UIViewController+Peekable.swift","Wikipedia/Code/UIViewController+WMFAlerts.swift","Wikipedia/Code/ViewController+URLHandling.swift","Wikipedia/Code/UIViewController+Extensions.swift","Wikipedia/Code/FundraisingAnnouncementPanel.swift","Wikipedia/Code/UIViewController+WMFEmptyView.swift","Wikipedia/Code/UIViewController+ProfileButton.swift","Wikipedia/Code/WMFReferencePageViewController.swift","Wikipedia/Code/WMFAppViewController+Extensions.swift","Wikipedia/Code/UIViewController+WMFHideKeyboard.swift","Wikipedia/Code/UIViewController+WMFStoryboardUtilities.h","Wikipedia/Code/UIViewController+WMFStoryboardUtilities.m","Wikipedia/Code/UIViewController+WMFChildViewController.swift","Wikipedia/Code/UIViewController+WMFStoryboardUtilities.swift","Wikipedia/Code/UIVIewController+WMFCommonRotationSupport.swift","WikipediaUnitTests/Code/UIViewController+WMFSearchButtonTests.m","Wikipedia/Code/UIViewController+DescriptionWelcomeStoryboard.swift","WMFComponents/Sources/WMFComponents/Extensions/UIViewController+Extensions.swift","WMFComponents/Sources/WMFComponents/Components/Shared/Toasts/WMFToastPresenter.swift"],"code":"extension UIViewController {\n    @objc(wmf_pushViewController:animated:)\n    func push(_ viewController: UIViewController, animated: Bool = true) {\n        \n        if let navigationController = navigationController {\n            if #available(iOS 18, *) {\n                if UIDevice.current.userInterfaceIdiom == .pad {\n                    // Need to do some fanciness here to handle iPad floating tab bar layout\n                    if navigationController.navigationBar.isHidden {\n                        navigationController.setNavigationBarHidden(false, animated: true)\n                        DispatchQueue.main.asyncAfter(deadline: .now() + 0.2) {\n                            navigationController.pushViewController(viewController, animated: true)\n                        }\n                    } else {\n                        navigationController.pushViewController(viewController, animated: true)\n                    }\n                } else {\n                    navigationController.pushViewController(viewController, animated: true)\n                }\n            } else {\n                navigationController.pushViewController(viewController, animated: true)\n            }\n        } else if let presentingViewController = presentingViewController {\n            presentingViewController.dismiss(animated: true) {\n                presentingViewController.push(viewController, animated: animated)\n            }\n        } else if let parent = parent {\n            parent.push(viewController, animated: animated)\n        } else if let navigationController = self as? UINavigationController {\n            navigationController.pushViewController(viewController, animated: animated)\n        }\n    }\n}","file":"Wikipedia/Code/UIViewController+Push.swift","kind":"extension","line":3,"members":{"push":[4,34]},"supers":[]},"View":{"alsoIn":["WMFComponents/Sources/WMFComponents/Extensions/View+SnapshotUIImage.swift","WMFComponents/Sources/WMFComponents/Style/Extensions/View+Extensions.swift","WMFComponents/Sources/WMFComponents/Components/Shared/Buttons/CapsuleButtonStyle.swift"],"code":"extension View {\n\n    func readableShadow(intensity: Double = 0.80) -> some View {\n        return self.shadow(color: Color.black.opacity(intensity), radius: 5, x:0, y: 0)\n    }\n\n    /// Adds an iOS-version dependent `List` background `Color`\n    /// - Parameters:\n    ///   - color: `Color` to use as background\n    ///   - edges: safe area edges to ignore\n    /// - Returns: a modified `View` with the desired background `Color` applied\n    @ViewBuilder\n    func listBackgroundColor(_ color: Color, ignoringSafeAreaEdges edges: Edge.Set = .all) -> some View {\n        self.scrollContentBackground(.hidden)\n            .background(color).edgesIgnoringSafeArea(edges)\n\n    }\n\n    /// Sets container background of the view to `Color.clear` if on iOS 17\n    /// - Returns: a modified `View` with the iOS 17 container background modifier applied if needed\n    @ViewBuilder\n    func clearWidgetContainerBackground() -> some View {\n        self.containerBackground(for: .widget) {\n            Color.clear\n        }\n    }\n\n}","file":"Widgets/Utilities/View+Extensions.swift","kind":"extension","line":3,"members":{"clearWidgetContainerBackground":[21,28],"listBackgroundColor":[9,19],"readableShadow":[5,7]},"supers":[]},"WMFLanguagesViewControllerDelegate":{"code":"/*\n * Protocol for notifying languageSelectionDelegate that selection was made.\n * It is the receiver's responsibility to perform the appropriate action and dismiss the sender.\n */\n@protocol WMFLanguagesViewControllerDelegate <NSObject>\n\n@optional\n- (void)languagesController:(WMFLanguagesViewController * _Nonnull)controller didSelectLanguage:(MWKLanguageLink * _Nonnull)language;\n\n@end","file":"Wikipedia/Code/WMFLanguagesViewControllerDelegate.h","kind":"protocol","line":3,"members":{},"supers":["NSObject"]},"WMFLegacyFetcher":{"alsoIn":["WMF Framework/WMFLegacyFetcher.m","WMF Framework/WMFLegacyFetcher.m"],"code":"// Bridge from old Obj-C fetcher classes to new Swift fetcher class\n@interface WMFLegacyFetcher : NSObject\n\n- (instancetype)initWithSession:(WMFSession *)session configuration:(WMFConfiguration *)configuration NS_DESIGNATED_INITIALIZER;\n- (instancetype)init;\n\n@property (nonatomic, readonly) WMFSession *session;\n@property (nonatomic, readonly) WMFConfiguration *configuration;\n@property (nonatomic, strong, readonly) WMFFetcher *fetcher;\n\n- (NSString *)performMediaWikiAPIPOSTWithCSRFTokenForURL:(NSURL *)URL withBodyParameters:(NSDictionary<NSString *, NSString *> *)bodyParameters completionHandler:(void (^)(NSDictionary<NSString *,id> * _Nullable result, NSHTTPURLResponse * _Nullable response, NSError * _Nullable error))completionHandler;\n- (NSURLSessionTask *)performMediaWikiAPIGETForURL:(NSURL *)URL withQueryParameters:(NSDictionary<NSString *, id> *)queryParameters completionHandler:(void (^)(NSDictionary<NSString *,id> * _Nullable result, NSHTTPURLResponse * _Nullable response, NSError * _Nullable error)) completionHandler;\n- (NSURLSessionTask *)performMediaWikiAPIGETForURLRequest:(NSURLRequest *)urlRequest completionHandler:(void (^)(NSDictionary<NSString *,id> * _Nullable result, NSHTTPURLResponse * _Nullable response, NSError * _Nullable error)) completionHandler;\n- (NSURLSessionTask *)performCancelableMediaWikiAPIGETForURL:(NSURL *)URL cancellationKey:(NSString *)cancellationKey withQueryParameters:(NSDictionary<NSString *, id> *)queryParameters completionHandler:(void (^)(NSDictionary<NSString *,id> * _Nullable result, NSHTTPURLResponse * _Nullable response, NSError * _Nullable error)) completionHandler;\n- (NSURLSessionTask *)performMediaWikiAPIPOSTForURL:(NSURL *)URL withBodyParameters:(NSDictionary<NSString *, id> *)bodyParameters completionHandler:(void (^)(NSDictionary<NSString *,id> * _Nullable result, NSHTTPURLResponse * _Nullable response, NSError * _Nullable error))completionHandler;\n\n- (void)resolveMediaWikiApiErrorFromResult: (NSDictionary<NSString *, id> *)result siteURL:(NSURL *)siteURL completionHandler:(void (^)(MediaWikiAPIDisplayError * displayError)) completionHandler;\n\n- (void)cancelAllFetches; // only cancels tasks started with the methods provided by WMFLegacyFetcher - tasks started directly on the session are not canceled\n- (void)cancelTaskWithCancellationKey:(NSString *)cancellationKey;\n\n@end","file":"WMF Framework/WMFLegacyFetcher.h","kind":"class","line":10,"members":{"cancelAllFetches":[28,28],"cancelTaskWithCancellationKey:":[28,29],"configuration":[17,17],"dealloc":[27,29],"fetcher":[18,18],"init":[14,14],"initWithSession:configuration:":[19,25],"initWithSession:configuration:NS_DESIGNATED_INITIALIZER:":[13,13],"performCancelableMediaWikiAPIGETForURL:cancellationKey:withQueryParameters:completionHandler:":[23,23],"performCancelableMediaWikiAPIGETForURLRequest:cancellationKey:completionHandler:":[59,61],"performMediaWikiAPIGETForURL:withQueryParameters:completionHandler:":[21,21],"performMediaWikiAPIGETForURLRequest:completionHandler:":[22,22],"performMediaWikiAPIPOSTForURL:withBodyParameters:completionHandler:":[24,24],"performMediaWikiAPIPOSTWithCSRFTokenForURL:withBodyParameters:completionHandler:":[20,20],"resolveMediaWikiApiErrorFromResult:siteURL:completionHandler:":[26,26],"session":[16,16]},"supers":["NSObject"]},"WMFNavigationBarConfiguring":{"alsoIn":["WMFComponents/Sources/WMFComponents/Extensions/Navigation Bar/WMFNavigationBarConfiguring.swift"],"code":"public protocol WMFNavigationBarConfiguring {\n    \n}","file":"WMFComponents/Sources/WMFComponents/Extensions/Navigation Bar/WMFNavigationBarConfiguring.swift","kind":"protocol","line":5,"members":{"addOrUpdateUpperLeadingLargeTitleLabel":[378,420],"badgedProfileGlyphColor":[365,370],"configureNavigationBar":[112,298],"currentProfileBarButtonItem":[332,337],"customizeNavBarAppearance":[300,306],"hideCustomLeadingLargeTitleLabel":[431,434],"profileButtonAccessibilityID":[108,110],"profileButtonAccessibilityStrings":[372,374],"profileButtonImage":[352,363],"removeCustomLeadingLargeTitleLabel":[422,424],"resetNavBarAppearance":[308,315],"showCustomLeadingLargeTitleLabel":[436,439],"themeNavigationBarCustomCenteredTitleView":[325,330],"themeNavigationBarCustomLeadingLargeTitle":[426,429],"themeNavigationBarLeadingTitleView":[317,323],"updateNavigationBarProfileButton":[339,350],"upperLeadingLargeTitleTag":[376,378]},"supers":[]},"WMFPreferredLanguagesViewControllerDelegate":{"code":"@protocol WMFPreferredLanguagesViewControllerDelegate <WMFLanguagesViewControllerDelegate>\n\n@optional\n- (void)languagesController:(WMFPreferredLanguagesViewController *)controller didUpdatePreferredLanguages:(NSArray<MWKLanguageLink *> *)languages;\n\n@end","file":"Wikipedia/Code/WMFLanguagesViewController.h","kind":"protocol","line":42,"members":{},"supers":["WMFLanguagesViewControllerDelegate"]},"WMFSearchFetcher":{"alsoIn":["Wikipedia/Code/WMFSearchFetcher.m","Wikipedia/Code/SearchResultsLoader.swift","Wikipedia/Code/WMFSearchFetcher_Testing.h"],"appearsIn":[["search","h-classes","Logic \u00b7 class diagram"],["search","h-sequence","Type a query \u00b7 sequence"]],"code":"@interface WMFSearchFetcher : WMFLegacyFetcher\n\n- (void)fetchArticlesForSearchTerm:(NSString *)searchTerm\n                           siteURL:(NSURL *)siteURL\n                       resultLimit:(NSUInteger)resultLimit\n                           failure:(WMFErrorHandler)failure\n                           success:(WMFSearchResultsHandler)success;\n\n- (void)fetchArticlesForSearchTerm:(NSString *)searchTerm\n                           siteURL:(NSURL *)siteURL\n                       resultLimit:(NSUInteger)resultLimit\n                    fullTextSearch:(BOOL)fullTextSearch\n           appendToPreviousResults:(nullable WMFSearchResults *)results\n                           failure:(WMFErrorHandler)failure\n                           success:(WMFSearchResultsHandler)success;\n\n- (void)fetchFilesForSearchTerm:(NSString *)searchTerm\n                       resultLimit:(NSUInteger)resultLimit\n                    fullTextSearch:(BOOL)fullTextSearch\n           appendToPreviousResults:(nullable WMFSearchResults *)results\n                           failure:(WMFErrorHandler)failure\n                           success:(WMFSearchResultsHandler)success;\n@end","file":"Wikipedia/Code/WMFSearchFetcher.h","kind":"class","line":10,"members":{"fetchArticles":[64,84],"fetchArticlesForSearchTerm:siteURL:resultLimit:failure:success:":[12,16],"fetchArticlesForSearchTerm:siteURL:resultLimit:fullTextSearch:appendToPreviousResults:failure:success:":[18,24],"fetchFilesForSearchTerm:resultLimit:fullTextSearch:appendToPreviousResults:failure:success:":[26,31],"performSearchRequestForSearchTerm:url:queryParameters:fullTextSearch:appendToPreviousResults:failure:success:":[96,135],"setSearchID:onResults:fullTextSearch:":[137,143]},"supers":["WMFLegacyFetcher"]},"WMFSearchResultsView":{"appearsIn":[["search","h-widgets","Screen \u00b7 view composition"]],"code":"public struct WMFSearchResultsView: View {\n\n    @ObservedObject var appEnvironment = WMFAppEnvironment.current\n    @ObservedObject var viewModel: WMFSearchResultsViewModel\n    @AccessibilityFocusState private var focusedElementID: String?\n\n    private var theme: WMFTheme {\n        appEnvironment.theme\n    }\n\n    public init(viewModel: WMFSearchResultsViewModel) {\n        self.viewModel = viewModel\n    }\n\n    public var body: some View {\n        ZStack {\n            Color(theme.paperBackground)\n                .ignoresSafeArea()\n            if let emptyState = viewModel.emptyState, !viewModel.showsSemanticSearchEntryPointInsteadOfEmptyState {\n                WMFEmptyView(viewModel: emptyViewModel(for: emptyState), type: .noItems, isScrollable: true)\n                    .padding(.top, viewModel.topPadding)\n            } else {\n                resultsList\n            }\n        }\n    }\n\n    private func emptyViewModel(for state: WMFSearchResultsViewModel.EmptyState) -> WMFEmptyViewModel {\n        switch state {\n        case .noResults:\n            return WMFEmptyViewModel(\n                localizedStrings: WMFEmptyViewModel.LocalizedStrings(title: viewModel.localizedStrings.noResultsMessage, subtitle: \"\", titleFilter: nil, buttonTitle: nil, attributedFilterString: nil),\n                image: nil,\n                imageColor: nil,\n                numberOfFilters: nil)\n        case .noInternetConnection:\n            return WMFEmptyViewModel(\n                localizedStrings: WMFEmptyViewModel.LocalizedStrings(title: viewModel.localizedStrings.noInternetConnectionTitle, subtitle: \"\", titleFilter: nil, buttonTitle: nil, attributedFilterString: nil),\n                image: viewModel.noInternetConnectionImage,\n                imageColor: appEnvironment.theme.secondaryText,\n                numberOfFilters: nil,\n                imageSize: nil)\n        }\n    }\n\n    private var resultsList: some View {\n        List {\n            if let semanticSearchEntryPointViewModel = viewModel.semanticSearchEntryPointViewModel {\n                WMFSemanticSearchEntryPointView(viewModel: semanticSearchEntryPointViewModel, horizontalPadding: viewModel.horizontalPadding)\n                    .environment(\\.layoutDirection, viewModel.isRightToLeft ? .rightToLeft : .leftToRight)\n                    .listRowInsets(EdgeInsets())\n                    .listRowBackground(Color(theme.paperBackground))\n                    .listRowSeparator(.hidden)\n                    .accessibilityIdentifier(AccessibilityIdentifiers.Search.semanticSearchEntryPoint)\n                    .accessibilityFocused($focusedElementID, equals: WMFSearchResultsViewModel.semanticSearchEntryPointAccessibilityID)\n            }\n            ForEach(viewModel.results) { result in\n                WMFSearchResultRow(viewModel: viewModel, result: result, focusedElementID: $focusedElementID)\n            }\n        }\n        .listStyle(.plain)\n        .onChange(of: viewModel.accessibilityFocusRequestID) { _, _ in\n            focusedElementID = viewModel.firstAccessibilityElementID\n        }\n        .scrollContentBackground(.hidden)\n        .scrollDismissesKeyboard(.never)\n        .contentMargins(.top, viewModel.topPadding, for: .scrollContent)\n    }\n}","file":"WMFComponents/Sources/WMFComponents/Components/Search/Results/WMFSearchResultsView.swift","kind":"struct","line":3,"members":{"WMFSearchResultsView":[13,15],"appEnvironment":[5,5],"body":[17,28],"emptyViewModel":[30,46],"focusedElementID":[7,7],"resultsList":[48,70],"theme":[9,11],"viewModel":[6,6]},"supers":["View"]},"WMFSearchResultsViewModel":{"appearsIn":[["search","h-classes","Logic \u00b7 class diagram"],["search","h-widgets","Screen \u00b7 view composition"],["search","h-sequence","Type a query \u00b7 sequence"]],"code":"@MainActor\npublic final class WMFSearchResultsViewModel: ObservableObject {\n\n    public struct LocalizedStrings {\n        let openActionTitle: String\n        let openInNewTabActionTitle: String\n        let openInBackgroundTabActionTitle: String\n        let saveActionTitle: String\n        let unsaveActionTitle: String\n        let shareActionTitle: String\n        let viewOnMapActionTitle: String\n        let noResultsMessage: String\n        let noInternetConnectionTitle: String\n\n        public init(\n            openActionTitle: String,\n            openInNewTabActionTitle: String,\n            openInBackgroundTabActionTitle: String,\n            saveActionTitle: String,\n            unsaveActionTitle: String,\n            shareActionTitle: String,\n            viewOnMapActionTitle: String,\n            noResultsMessage: String,\n            noInternetConnectionTitle: String\n        ) {\n            self.openActionTitle = openActionTitle\n            self.openInNewTabActionTitle = openInNewTabActionTitle\n            self.openInBackgroundTabActionTitle = openInBackgroundTabActionTitle\n            self.saveActionTitle = saveActionTitle\n            self.unsaveActionTitle = unsaveActionTitle\n            self.shareActionTitle = shareActionTitle\n            self.viewOnMapActionTitle = viewOnMapActionTitle\n            self.noResultsMessage = noResultsMessage\n            self.noInternetConnectionTitle = noInternetConnectionTitle\n        }\n    }\n\n    public struct SearchResult: Identifiable, Equatable, Sendable {\n        public let articleURL: URL\n        public let pageTitle: String\n        public let title: String\n        public let titleHTML: String\n        public let description: String?\n        public let thumbnailURL: URL?\n        public let isArticle: Bool\n        public let hasLocation: Bool\n        public let isSavable: Bool\n        public var isSaved: Bool\n\n        public var id: String {\n            articleURL.absoluteString\n        }\n\n        var displayedDescription: String? {\n            description?.components(separatedBy: \"\\n\").first\n        }\n\n        public init(\n            articleURL: URL,\n            pageTitle: String,\n            title: String,\n            titleHTML: String,\n            description: String?,\n            thumbnailURL: URL?,\n            isArticle: Bool = true,\n            hasLocation: Bool = false,\n            isSavable: Bool = true,\n            isSaved: Bool = false\n        ) {\n            self.articleURL = articleURL\n            self.pageTitle = pageTitle\n            self.title = title\n            self.titleHTML = titleHTML\n            self.description = description\n            self.thumbnailURL = thumbnailURL\n            self.isArticle = isArticle\n            self.hasLocation = hasLocation\n            self.isSavable = isSavable\n            self.isSaved = isSaved\n        }\n    }\n\n    public enum EmptyState: Equatable, Sendable {\n        case noResults\n        case noInternetConnection\n    }\n\n    public enum ActionSource: Sendable {\n        case swipe\n        case contextMenu\n    }\n\n    public typealias ResultAction = @MainActor @Sendable (SearchResult, Int) -> Void\n    public typealias SaveAction = @MainActor @Sendable (SearchResult, Int, ActionSource) -> Void\n    public typealias ShareAction = @MainActor @Sendable (SearchResult, Int, CGRect?, ActionSource) -> Void\n    public typealias IsSavedAction = @MainActor @Sendable (SearchResult) -> Bool\n    public typealias SummaryProvider = @Sendable (WMFProject, String) async throws -> WMFArticleSummary\n\n    @Published private(set) var results: [SearchResult] = []\n    @Published private(set) var searchTerm: String?\n    @Published private(set) var emptyState: EmptyState?\n    @Published private(set) var project: WMFProject?\n    @Published private(set) var isRightToLeft: Bool = false\n    @Published public private(set) var semanticSearchEntryPointViewModel: WMFSemanticSearchEntryPointViewModel?\n    @Published private(set) var accessibilityFocusRequestID = 0\n    private var hasPendingAccessibilityFocusRequest = false\n\n    static let semanticSearchEntryPointAccessibilityID = \"semantic-search-entry-point\"\n    @Published public var topPadding: CGFloat = 0\n    @Published public var horizontalPadding: CGFloat = 16\n\n    let localizedStrings: LocalizedStrings\n    let noInternetConnectionImage: UIImage?\n    var geometryFrames: [String: CGRect] = [:]\n\n    private let isSavedAction: IsSavedAction\n    private let tapAction: ResultAction\n    private let openAction: ResultAction\n    private let openInNewTabAction: ResultAction\n    private let openInBackgroundTabAction: ResultAction\n    private let openOnMapAction: ResultAction\n    private let saveOrUnsaveAction: SaveAction\n    private let shareAction: ShareAction\n    private let summaryProvider: SummaryProvider\n\n    public init(\n        localizedStrings: LocalizedStrings,\n        noInternetConnectionImage: UIImage?,\n        isSavedAction: @escaping IsSavedAction,\n        tapAction: @escaping ResultAction,\n        openAction: @escaping ResultAction,\n        openInNewTabAction: @escaping ResultAction,\n        openInBackgroundTabAction: @escaping ResultAction,\n        openOnMapAction: @escaping ResultAction,\n        saveOrUnsaveAction: @escaping SaveAction,\n        shareAction: @escaping ShareAction,\n        summaryProvider: SummaryProvider? = nil\n    ) {\n        self.localizedStrings = localizedStrings\n        self.noInternetConnectionImage = noInternetConnectionImage\n        self.isSavedAction = isSavedAction\n        self.tapAction = tapAction\n        self.openAction = openAction\n        self.openInNewTabAction = openInNewTabAction\n        self.openInBackgroundTabAction = openInBackgroundTabAction\n        self.openOnMapAction = openOnMapAction\n        self.saveOrUnsaveAction = saveOrUnsaveAction\n        self.shareAction = shareAction\n        self.summaryProvider = summaryProvider ?? { project, title in\n            try await WMFArticleSummaryDataController.shared.fetchArticleSummary(project: project, title: title)\n        }\n    }\n\n    // MARK: - Public\n\n    public func showResults(_ newResults: [SearchResult], searchTerm: String?, project: WMFProject?) {\n        self.searchTerm = searchTerm\n        self.project = project\n        isRightToLeft = project?.isRTL ?? false\n        results = newResults.map { result in\n            var result = result\n            result.isSaved = isSavedAction(result)\n            return result\n        }\n        emptyState = results.isEmpty ? .noResults : nil\n        fulfillPendingAccessibilityFocusRequest()\n    }\n\n    public func showEmptyState(_ state: EmptyState) {\n        results = []\n        emptyState = state\n        hasPendingAccessibilityFocusRequest = false\n    }\n\n    public func reset() {\n        results = []\n        searchTerm = nil\n        emptyState = nil\n    }\n\n    public func showSemanticSearchEntryPoint(_ viewModel: WMFSemanticSearchEntryPointViewModel) {\n        semanticSearchEntryPointViewModel = viewModel\n        fulfillPendingAccessibilityFocusRequest()\n    }\n\n    public func hideSemanticSearchEntryPoint() {\n        semanticSearchEntryPointViewModel = nil\n    }\n\n    /// A search with no lexical results still offers the semantic search entry point, so the list\n    /// shows the card alone instead of the no results message.\n    var showsSemanticSearchEntryPointInsteadOfEmptyState: Bool {\n        emptyState == .noResults && semanticSearchEntryPointViewModel != nil\n    }\n\n    var firstAccessibilityElementID: String? {\n        semanticSearchEntryPointViewModel != nil ? Self.semanticSearchEntryPointAccessibilityID : results.first?.id\n    }\n\n    /// Moves VoiceOver to the first element of the list on the next layout pass. Used when the\n    /// keyboard goes away, so the reader lands on the first result instead of the one closest to the\n    /// search field.\n    public func requestAccessibilityFocusOnFirstElement() {\n        guard firstAccessibilityElementID != nil else {\n            hasPendingAccessibilityFocusRequest = true\n            return\n        }\n        hasPendingAccessibilityFocusRequest = false\n        accessibilityFocusRequestID += 1\n    }\n\n    private func fulfillPendingAccessibilityFocusRequest() {\n        guard hasPendingAccessibilityFocusRequest, firstAccessibilityElementID != nil else { return }\n        hasPendingAccessibilityFocusRequest = false\n        accessibilityFocusRequestID += 1\n    }\n\n    public func refreshSavedStates() {\n        var didChange = false\n        let refreshedResults = results.map { result in\n            var result = result\n            let isSaved = isSavedAction(result)\n            if result.isSaved != isSaved {\n                result.isSaved = isSaved\n                didChange = true\n            }\n            return result\n        }\n        if didChange {\n            results = refreshedResults\n        }\n    }\n\n    // MARK: - Internal\n\n    var languageCode: String? {\n        guard case .wikipedia(let language) = project else { return nil }\n        return language.languageCode\n    }\n\n    func accessibilityText(_ text: String) -> AttributedString {\n        var attributedText = AttributedString(text)\n        attributedText.languageIdentifier = languageCode\n        return attributedText\n    }\n\n    func attributedTitle(for result: SearchResult, styles: HtmlUtils.Styles, boldFont: UIFont) -> AttributedString {\n        var attributedTitle = (try? HtmlUtils.attributedStringFromHtml(result.titleHTML, styles: styles)) ?? AttributedString(result.titleHTML)\n\n        if let searchTerm, !searchTerm.isEmpty,\n           let range = attributedTitle.range(of: searchTerm, options: .caseInsensitive) {\n            attributedTitle[range].font = boldFont\n        }\n        attributedTitle.languageIdentifier = languageCode\n        return attributedTitle\n    }\n\n    func previewViewModel(for result: SearchResult) -> WMFArticlePreviewViewModel {\n        WMFArticlePreviewViewModel(\n            url: result.articleURL,\n            titleHtml: result.title,\n            description: result.displayedDescription,\n            imageURL: result.thumbnailURL,\n            isSaved: result.isSaved,\n            snippet: nil\n        )\n    }\n\n    func loadPreviewViewModel(for result: SearchResult) async -> WMFArticlePreviewViewModel {\n        guard let project, let summary = try? await summaryProvider(project, result.pageTitle) else {\n            return previewViewModel(for: result)\n        }\n\n        return WMFArticlePreviewViewModel(\n            url: result.articleURL,\n            titleHtml: result.title,\n            description: summary.description ?? result.displayedDescription,\n            imageURL: summary.thumbnailURL ?? result.thumbnailURL,\n            isSaved: result.isSaved,\n            snippet: summary.extract\n        )\n    }\n\n    func loadImage(url: URL?) async -> UIImage? {\n        guard let url,\n              let data = try? await WMFImageDataController.shared.fetchImageData(url: url),\n              let image = UIImage(data: data) else {\n            return nil\n        }\n\n        guard let faceUnitRect = try? await WMFFaceDetectionCache.shared.faceBounds(in: image, for: url) else {\n            return image\n        }\n\n        return image.croppedToSquare(around: faceUnitRect)\n    }\n\n    func tap(_ result: SearchResult) {\n        guard let index = index(of: result) else { return }\n\n        tapAction(result, index)\n    }\n\n    func open(_ result: SearchResult) {\n        guard let index = index(of: result) else { return }\n\n        openAction(result, index)\n    }\n\n    func openInNewTab(_ result: SearchResult) {\n        guard let index = index(of: result) else { return }\n\n        openInNewTabAction(result, index)\n    }\n\n    func openInBackgroundTab(_ result: SearchResult) {\n        guard let index = index(of: result) else { return }\n\n        openInBackgroundTabAction(result, index)\n    }\n\n    func openOnMap(_ result: SearchResult) {\n        guard let index = index(of: result) else { return }\n\n        openOnMapAction(result, index)\n    }\n\n    func saveOrUnsave(_ result: SearchResult, source: ActionSource) {\n        guard let index = index(of: result) else { return }\n\n        saveOrUnsaveAction(result, index, source)\n    }\n\n    func share(_ result: SearchResult, source: ActionSource) {\n        guard let index = index(of: result) else { return }\n\n        shareAction(result, index, geometryFrames[result.id], source)\n    }\n\n    private func index(of result: SearchResult) -> Int? {\n        results.firstIndex(where: { $0.id == result.id })\n    }\n}","file":"WMFComponents/Sources/WMFComponents/Components/Search/Results/WMFSearchResultsViewModel.swift","kind":"class","line":4,"members":{"WMFSearchResultsViewModel":[129,155],"accessibilityFocusRequestID":[108,108],"accessibilityText":[244,248],"attributedTitle":[250,259],"emptyState":[104,104],"firstAccessibilityElementID":[199,201],"fulfillPendingAccessibilityFocusRequest":[215,219],"geometryFrames":[117,117],"hasPendingAccessibilityFocusRequest":[109,109],"hideSemanticSearchEntryPoint":[189,191],"horizontalPadding":[113,113],"index":[343,345],"isRightToLeft":[106,106],"isSavedAction":[119,119],"languageCode":[237,242],"loadImage":[287,299],"loadPreviewViewModel":[272,285],"localizedStrings":[115,115],"noInternetConnectionImage":[116,116],"open":[307,311],"openAction":[121,121],"openInBackgroundTab":[319,323],"openInBackgroundTabAction":[123,123],"openInNewTab":[313,317],"openInNewTabAction":[122,122],"openOnMap":[325,329],"openOnMapAction":[124,124],"previewViewModel":[261,270],"project":[105,105],"refreshSavedStates":[221,235],"requestAccessibilityFocusOnFirstElement":[203,213],"reset":[178,182],"results":[102,102],"saveOrUnsave":[331,335],"saveOrUnsaveAction":[125,125],"searchTerm":[103,103],"semanticSearchEntryPointAccessibilityID":[111,111],"semanticSearchEntryPointViewModel":[107,107],"share":[337,341],"shareAction":[126,126],"showEmptyState":[172,176],"showResults":[157,170],"showSemanticSearchEntryPoint":[184,187],"showsSemanticSearchEntryPointInsteadOfEmptyState":[193,197],"summaryProvider":[127,127],"tap":[301,305],"tapAction":[120,120],"topPadding":[112,112]},"supers":["ObservableObject"]},"WMFSemanticSearchFeedbackPromptDelegate":{"code":"/// Decides whether the sheet may show the feedback prompt, and learns when it shows. The app side\n/// implements it, so the prompt follows the search session instead of one sheet.\n@MainActor\npublic protocol WMFSemanticSearchFeedbackPromptDelegate: AnyObject {\n    var canShowSheetFeedbackPrompt: Bool { get }\n    func sheetFeedbackPromptDidAppear()\n}","file":"WMFComponents/Sources/WMFComponents/Components/Search/Semantic Search Results/WMFSemanticSearchResultsViewModel.swift","kind":"protocol","line":14,"members":{"canShowSheetFeedbackPrompt":[18,18],"sheetFeedbackPromptDidAppear":[19,19]},"supers":["AnyObject"]},"WMFSemanticSearchResultsLoggingDelegate":{"code":"/// Receives the moments of the sheet that the instrumentation records. The app side implements it.\n@MainActor\npublic protocol WMFSemanticSearchResultsLoggingDelegate: AnyObject {\n    func logResultsImpression(searchID: String?)\n    func logEmptyResultsImpression()\n    /// position is 1-indexed\n    func logResultTap(position: Int, searchID: String?)\n}","file":"WMFComponents/Sources/WMFComponents/Components/Search/Semantic Search Results/WMFSemanticSearchResultsViewModel.swift","kind":"protocol","line":5,"members":{"logEmptyResultsImpression":[9,9],"logResultTap":[10,11],"logResultsImpression":[8,8]},"supers":["AnyObject"]},"YearInReviewBadgeDelegate":{"code":"@objc public protocol YearInReviewBadgeDelegate: AnyObject {\n    @objc func updateYIRBadgeVisibility()\n}","file":"WMFComponents/Sources/WMFComponents/Coordinator/YearInReviewBadgeDelegate.swift","kind":"protocol","line":3,"members":{"updateYIRBadgeVisibility":[4,4]},"supers":["AnyObject"]}},"sourceUrl":"https://github.com/wikimedia/wikipedia-ios/blob/f002b78bca2e580e7bbed7dfb6fd54a0967bcc08/"};
